#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct StoredAlignmentSensitiveContentIdentity {
    algorithm: String,
    size_bytes: u64,
    modified_unix_ms: u64,
    first_sample_digest: String,
    middle_sample_digest: String,
    last_sample_digest: String,
}

impl StoredAlignmentSensitiveContentIdentity {
    fn to_media_content_identity(&self) -> Result<MediaContentIdentity, String> {
        if self.algorithm != "sha256-full-file-v2"
            || self.first_sample_digest.len() != 64
            || !self
                .first_sample_digest
                .bytes()
                .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
            || self.first_sample_digest != self.middle_sample_digest
            || self.middle_sample_digest != self.last_sample_digest
        {
            return Err("本机训练证据中的媒体全文件身份无效。".to_string());
        }
        Ok(MediaContentIdentity {
            algorithm: "sha256-full-file-v2",
            size_bytes: self.size_bytes,
            modified_unix_ms: self.modified_unix_ms,
            first_sample_digest: self.first_sample_digest.clone(),
            middle_sample_digest: self.middle_sample_digest.clone(),
            last_sample_digest: self.last_sample_digest.clone(),
        })
    }
}

