fn validate_alignment_sensitive_sha256(value: &str, label: &str) -> Result<(), String> {
    if value.len() != 71
        || !value.starts_with("sha256:")
        || !value[7..]
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
    {
        return Err(format!("{label}无效。"));
    }
    Ok(())
}

fn alignment_sensitive_pack_sha256(value: &serde_json::Value) -> Result<String, String> {
    let canonical = canonicalize_alignment_benchmark_json(value)?;
    Ok(format!(
        "sha256:{}",
        sha256_alignment_benchmark_bytes(canonical.as_bytes())
    ))
}

fn stored_alignment_media<'a>(
    manifest: &'a StoredAlignmentSensitiveManifest,
    media_id: &str,
) -> Result<
    (
        &'a StoredAlignmentSensitivePlanMedia,
        &'a StoredAlignmentSensitivePreparedMedia,
    ),
    String,
> {
    let planned = manifest
        .plan
        .media
        .iter()
        .find(|media| media.media_id == media_id)
        .ok_or_else(|| "本机训练证据缺少关系引用的计划媒体。".to_string())?;
    let prepared = manifest
        .prepared_media
        .iter()
        .find(|media| media.media_id == media_id)
        .ok_or_else(|| "本机训练证据缺少关系引用的已准备媒体。".to_string())?;
    Ok((planned, prepared))
}

fn stored_alignment_media_pack_value(
    planned: &StoredAlignmentSensitivePlanMedia,
    prepared: &StoredAlignmentSensitivePreparedMedia,
    preferred_audio_stream_index: Option<u32>,
    preferred_visual_stream_index: Option<u32>,
    fallback_duration_ms: u64,
    role: &str,
) -> Result<serde_json::Value, String> {
    let path = prepared
        .canonical_path
        .as_deref()
        .unwrap_or(prepared.requested_path.as_str());
    if path != planned.path {
        let planned_path = Path::new(&planned.path);
        let prepared_path = Path::new(path);
        if planned_path.canonicalize().ok().as_deref()
            != prepared_path.canonicalize().ok().as_deref()
        {
            return Err("本机训练证据中的计划路径与已准备路径不一致。".to_string());
        }
    }
    let stored_identity = prepared
        .content_identity
        .as_ref()
        .ok_or_else(|| format!("{role}缺少全文件内容身份。"))?;
    let expected_identity = stored_identity.to_media_content_identity()?;
    let current_identity = probe_alignment_run_expected_identity(path, None, role)?;
    if current_identity != expected_identity {
        return Err(format!(
            "blocked:media-identity-changed：{role}在匹配后发生变化，拒绝生成复核任务。"
        ));
    }
    let duration_ms = preferred_audio_stream_index
        .and_then(|stream_index| {
            prepared
                .audio_candidates
                .iter()
                .find(|candidate| candidate.stream.index == stream_index)
                .and_then(|candidate| candidate.media_duration_ms)
        })
        .or_else(|| {
            prepared
                .audio_candidates
                .iter()
                .filter_map(|candidate| candidate.media_duration_ms)
                .max()
        })
        .unwrap_or(fallback_duration_ms)
        .max(fallback_duration_ms);
    if duration_ms == 0 {
        return Err(format!("{role}缺少可用时长。"));
    }
    Ok(serde_json::json!({
        "path": path,
        "contentDigest": format!("sha256:{}", expected_identity.first_sample_digest),
        "durationMs": duration_ms,
        "videoStreamIndex": preferred_visual_stream_index
            .or(planned.requested_video_stream_index)
            .unwrap_or(0),
    }))
}

fn build_alignment_sensitive_blind_review_pack_inner(
    root: &Path,
    request: BuildAlignmentSensitiveBlindReviewPackRequest,
) -> Result<String, String> {
    validate_alignment_sensitive_sha256(&request.media_family_id, "媒体家族摘要")?;
    let (summary, payload) =
        read_verified_alignment_sensitive_manifest_payload(root, &request.run_id)?;
    if !summary.ready_for_training_intake {
        return Err("这次运行尚未满足真实证据整理条件。".to_string());
    }
    let pair_summary = summary
        .review_candidate_pairs
        .iter()
        .find(|pair| pair.pair_ordinal == request.pair_ordinal)
        .ok_or_else(|| "这组关系没有可用的高信息量复核窗口。".to_string())?;
    let manifest: StoredAlignmentSensitiveManifest = serde_json::from_value(payload)
        .map_err(|error| format!("本机训练证据内容结构无效：{error}"))?;
    if manifest.run_id != request.run_id {
        return Err("本机训练证据运行编号不一致。".to_string());
    }
    let pair = manifest
        .snapshot
        .pairs
        .iter()
        .find(|pair| pair.pair_ordinal == request.pair_ordinal)
        .ok_or_else(|| "完整运行清单缺少所选关系。".to_string())?;
    if pair.status != "completed"
        || alignment_sensitive_media_id_digest(&pair.source_media_id)
            != pair_summary.source_media_id_digest
        || alignment_sensitive_media_id_digest(&pair.target_media_id)
            != pair_summary.target_media_id_digest
    {
        return Err("复核候选与完整运行关系不一致。".to_string());
    }
    let time_map = pair
        .proposal
        .as_ref()
        .and_then(|proposal| proposal.time_map.as_ref())
        .ok_or_else(|| "所选关系没有可复核的时间映射。".to_string())?;
    let (source_plan, source_prepared) = stored_alignment_media(&manifest, &pair.source_media_id)?;
    let (target_plan, target_prepared) = stored_alignment_media(&manifest, &pair.target_media_id)?;
    let source = stored_alignment_media_pack_value(
        source_plan,
        source_prepared,
        time_map.source_stream.as_ref().map(|stream| stream.index),
        time_map
            .source_visual_stream
            .as_ref()
            .map(|stream| stream.index),
        time_map.source_end_ms,
        "参考 A",
    )?;
    let target = stored_alignment_media_pack_value(
        target_plan,
        target_prepared,
        time_map.target_stream.as_ref().map(|stream| stream.index),
        time_map
            .target_visual_stream
            .as_ref()
            .map(|stream| stream.index),
        time_map.target_end_ms,
        "原片 B",
    )?;
    let selector_receipt_body = serde_json::json!({
        "selectorVersion": ALIGNMENT_SENSITIVE_REVIEW_SELECTOR_VERSION,
        "manifestCanonicalPayloadDigest": summary.manifest_canonical_payload_digest,
        "pairOrdinal": request.pair_ordinal,
        "sourceMediaIdDigest": pair_summary.source_media_id_digest,
        "targetMediaIdDigest": pair_summary.target_media_id_digest,
        "tasks": pair_summary.tasks,
    });
    let selector_receipt_id = alignment_sensitive_pack_sha256(&selector_receipt_body)?;
    let run_id_digest = format!(
        "sha256:{:x}",
        Sha256::digest(
            format!(
                "danmaku-studio/alignment-sensitive-run-id/v1\n{}",
                request.run_id
            )
            .as_bytes()
        )
    );
    let mut tasks = Vec::with_capacity(pair_summary.tasks.len());
    for task in &pair_summary.tasks {
        let mut shuffled = task.candidate_timestamps_ms.clone();
        shuffled.sort_by_key(|timestamp| {
            Sha256::digest(format!("{}\n{timestamp}", task.query_key).as_bytes()).to_vec()
        });
        let candidate_slots = shuffled
            .into_iter()
            .enumerate()
            .map(|(index, timestamp_ms)| {
                serde_json::json!({
                    "slotId": char::from_u32(u32::from(b'A') + u32::try_from(index).unwrap_or(0))
                        .unwrap_or('A')
                        .to_string(),
                    "timestampMs": timestamp_ms,
                })
            })
            .collect::<Vec<_>>();
        let task_body = serde_json::json!({
            "queryKey": task.query_key,
            "sourceTimestampMs": task.source_timestamp_ms,
            "sourcePreviewStartMs": task.source_preview_start_ms,
            "sourcePreviewEndMs": task.source_preview_end_ms,
            "targetReviewStartMs": task.target_review_start_ms,
            "targetReviewEndMs": task.target_review_end_ms,
            "candidateSlots": candidate_slots,
        });
        let task_id = alignment_sensitive_pack_sha256(&task_body)?;
        let mut task_value = task_body;
        task_value
            .as_object_mut()
            .ok_or_else(|| "复核任务无法编码。".to_string())?
            .insert("taskId".to_string(), serde_json::Value::String(task_id));
        tasks.push(task_value);
    }
    tasks.sort_by(|left, right| left["queryKey"].as_str().cmp(&right["queryKey"].as_str()));
    let body = serde_json::json!({
        "schemaVersion": "alignment-blind-review-pack-v2",
        "mediaFamilyId": request.media_family_id,
        "provenance": {
            "kind": "realAlignmentRun",
            "runIdDigest": run_id_digest,
            "manifestPayloadDigest": summary.manifest_payload_digest,
            "manifestCanonicalPayloadDigest": summary.manifest_canonical_payload_digest,
            "selectorVersion": ALIGNMENT_SENSITIVE_REVIEW_SELECTOR_VERSION,
            "selectorReceiptId": selector_receipt_id,
            "pairOrdinal": request.pair_ordinal,
            "familyAuthority": "user-declared-label",
        },
        "source": source,
        "target": target,
        "tasks": tasks,
        "containsMediaPaths": true,
        "predictionsBlinded": true,
        "permission": "local-sensitive-blind-multimodal-review-only",
        "releaseEligible": false,
    });
    let pack_id = alignment_sensitive_pack_sha256(&body)?;
    let mut pack = body;
    pack.as_object_mut()
        .ok_or_else(|| "复核任务包无法编码。".to_string())?
        .insert("packId".to_string(), serde_json::Value::String(pack_id));
    let mut json = serde_json::to_string_pretty(&pack)
        .map_err(|error| format!("无法编码真实证据盲复核任务包：{error}"))?;
    json.push('\n');
    Ok(json)
}

