#[derive(Debug, Clone)]
struct PreparedV2BatchMediaEvidence {
    inputs: Vec<AlignmentAudioInput>,
    landmarks: HashMap<u32, CachedV2Landmarks>,
    extraction_notes: Vec<String>,
    retained_artifact_bytes: usize,
    toolchain_cache_identity: String,
}

struct PreparedAudioAlignmentBatchMedia {
    identity_guard: Arc<PinnedMediaIdentityGuard>,
    path: String,
    physical_group_index: usize,
    physical_object_key: PhysicalFileObjectKey,
    expected_identity: MediaContentIdentity,
    evidence: PreparedV2BatchMediaEvidence,
}

enum PreparedAudioAlignmentBatchMediaState {
    Ready(Arc<PreparedAudioAlignmentBatchMedia>),
    Failed {
        error: String,
        physical_group_index: Option<usize>,
    },
}

fn create_audio_alignment_sensitive_prepared_media(
    plan: &PlannedAudioAlignmentBatch,
    prepared: &[PreparedAudioAlignmentBatchMediaState],
) -> Result<Vec<AudioAlignmentSensitivePreparedMedia>, String> {
    if prepared.len() != plan.media.len() {
        return Err("本机敏感执行清单的预处理素材数量与批次计划不一致。".to_string());
    }
    plan.media
        .iter()
        .zip(prepared)
        .enumerate()
        .map(|(index, (planned, state))| {
            let base = |preparation_state, physical_group_ordinal, error| {
                AudioAlignmentSensitivePreparedMedia {
                    media_ordinal: index + 1,
                    media_id: planned.media_id.clone(),
                    role: planned.role,
                    requested_path: planned.path.clone(),
                    canonical_path: None,
                    requested_audio_stream_index: planned.requested_audio_stream_index,
                    requested_video_stream_index: planned.requested_video_stream_index,
                    preparation_state,
                    physical_group_ordinal,
                    content_identity: None,
                    audio_candidates: Vec::new(),
                    landmark_artifacts: Vec::new(),
                    extraction_notes: Vec::new(),
                    error,
                }
            };
            match state {
                PreparedAudioAlignmentBatchMediaState::Failed {
                    error,
                    physical_group_index,
                } => Ok(base(
                    "failed",
                    physical_group_index.map(|value| value + 1),
                    Some(error.clone()),
                )),
                PreparedAudioAlignmentBatchMediaState::Ready(media) => {
                    let mut audio_candidates = media
                        .evidence
                        .inputs
                        .iter()
                        .map(|input| {
                            let timeline = input.decode_timeline.as_ref();
                            AudioAlignmentSensitivePreparedAudioCandidate {
                                presentation_origin_ms: input.presentation_origin_ms,
                                media_duration_ms: input.media_duration_ms,
                                explicit_stream_selection: input.explicit_stream_selection,
                                stream: input.stream.clone(),
                                first_decoded_pts_ms: timeline
                                    .and_then(|value| value.first_decoded_pts_ms),
                                pts_discontinuity_count: timeline
                                    .map(|value| value.pts_discontinuity_count),
                                max_pts_gap_ms: timeline.and_then(|value| value.max_pts_gap_ms),
                                skip_samples: timeline.map(|value| value.skip_samples),
                                discard_padding: timeline.map(|value| value.discard_padding),
                                decoded_frame_count: timeline
                                    .map(|value| value.decoded_frame_count),
                                normalized_pcm_origin_ms: timeline
                                    .map(|value| value.normalized_pcm_origin_ms),
                            }
                        })
                        .collect::<Vec<_>>();
                    audio_candidates.sort_by_key(|candidate| candidate.stream.stream_index);
                    let mut landmark_artifacts = media
                        .evidence
                        .landmarks
                        .iter()
                        .map(|(stream_index, artifact)| {
                            let cache_origin = match artifact.cache_origin {
                                V2ArtifactCacheOrigin::NewMemoryOnly => "newMemoryOnly",
                                V2ArtifactCacheOrigin::NewPersistent => "newPersistent",
                                V2ArtifactCacheOrigin::Memory => "memory",
                                V2ArtifactCacheOrigin::Persistent => "persistent",
                            };
                            AudioAlignmentSensitiveLandmarkArtifact {
                                audio_stream_index: *stream_index,
                                cache_key: artifact.cache_key.as_str().to_string(),
                                cache_hit: artifact.cache_hit,
                                cache_origin,
                                cache_persistence_error: artifact.cache_persistence_error.clone(),
                                landmark_count: artifact.landmarks.len(),
                                coarse_fingerprint_count: artifact.coarse_fingerprint.len(),
                                spectral_backend_id: artifact.spectral_backend.backend_id.clone(),
                                requested_backend: artifact
                                    .spectral_backend
                                    .requested_backend
                                    .clone(),
                                backend_detail: artifact.spectral_backend.backend_detail.clone(),
                                fallback_reason: artifact.spectral_backend.fallback_reason.clone(),
                                presentation_start_ms: artifact.presentation_bounds.start_ms,
                                presentation_end_ms: artifact.presentation_bounds.end_ms,
                            }
                        })
                        .collect::<Vec<_>>();
                    landmark_artifacts.sort_by_key(|artifact| artifact.audio_stream_index);
                    Ok(AudioAlignmentSensitivePreparedMedia {
                        canonical_path: Some(media.path.clone()),
                        content_identity: Some(media.expected_identity.clone()),
                        audio_candidates,
                        landmark_artifacts,
                        extraction_notes: media.evidence.extraction_notes.clone(),
                        ..base("ready", Some(media.physical_group_index + 1), None)
                    })
                }
            }
        })
        .collect()
}

