#[serde(rename_all = "camelCase")]
pub struct AlignmentFeatureCacheStatus {
    coarse: AlignmentFeatureCacheBucketStatus,
    fine_pcm: AlignmentFeatureCacheBucketStatus,
    visual: AlignmentFeatureCacheBucketStatus,
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct AlignmentFeatureCacheClearReceipt {
    removed_files: usize,
    removed_bytes: u64,
    before: AlignmentFeatureCacheStatus,
    after: AlignmentFeatureCacheStatus,
}

#[tauri::command]
pub fn get_alignment_feature_cache_status() -> Result<AlignmentFeatureCacheStatus, String> {
    alignment_feature_cache_status()
}

#[tauri::command]
pub fn clear_alignment_feature_caches() -> Result<AlignmentFeatureCacheClearReceipt, String> {
    // Keep admission locked through deletion: a new run cannot start after the idle check.
        let coordinator = alignment_benchmark_coordinator()
            .lock()
            .map_err(|_| "原生对齐基准协调锁已损坏。".to_string())?;
        if coordinator.initializing
            || coordinator.session.is_some()
            || coordinator.ordinary_active_runs > 0
        {
            return Err(
                "媒体匹配或性能基准仍在运行；请先取消或等待完成，再清理特征缓存。".to_string(),
            );
        }
    let before = alignment_feature_cache_status()?;
    visual_aap::clear_cache()?;
    audio_feature_cache()
        .lock()
        .map_err(|_| "音频特征缓存锁已损坏。".to_string())?
        .clear();
    let coarse_removed = v2_audio_artifact_store().clear_all()?;
    let fine_removed = v2_fine_pcm_artifact_store().clear_all()?;
    let visual_removed = v2_visual_artifact_store().clear_all()?;
    let removed_files = coarse_removed
        .removed_files
        .saturating_add(fine_removed.removed_files)
        .saturating_add(visual_removed.removed_files);
    let removed_bytes = coarse_removed
        .removed_bytes
        .saturating_add(fine_removed.removed_bytes)
        .saturating_add(visual_removed.removed_bytes);
    let after = alignment_feature_cache_status()?;
    drop(coordinator);
    Ok(AlignmentFeatureCacheClearReceipt {
        removed_files,
        removed_bytes,
        before,
        after,
    })
}

#[tauri::command]
pub async fn align_audio_files(
    request: AudioAlignmentRequest,
) -> Result<AudioAlignmentProposal, String> {
    let spectral_backend_request = resolve_audio_alignment_request_spectral_backend(&request)?;
    let permit = acquire_ordinary_alignment_run()?;
    tauri::async_runtime::spawn_blocking(move || {
        let _permit = permit;
        align_audio_files_inner_with_spectral_backend_request(request, spectral_backend_request)
    })
    .await
    .map_err(|error| format!("本地音频对齐任务启动失败：{error}"))?
}

#[tauri::command]
pub async fn start_audio_alignment_job(
    request: AudioAlignmentRequest,
) -> Result<AudioAlignmentJobSnapshot, String> {
    let spectral_backend_request = resolve_audio_alignment_request_spectral_backend(&request)?;
    let permit = acquire_ordinary_alignment_run()?;
    let created = jobs::create_job()?;
    let job_id = created.job_id;
    let cancel_flag = created.cancel_flag;
    let worker_job_id = job_id.clone();
    tauri::async_runtime::spawn_blocking(move || {
        let _permit = permit;
        run_audio_alignment_job(
            worker_job_id,
            cancel_flag,
            request,
            spectral_backend_request,
        );
    });
    jobs::get_job(&job_id)
}

