#[tauri::command]
pub async fn start_audio_alignment_batch_job(
    app: tauri::AppHandle,
    request: AudioAlignmentBatchRequest,
) -> Result<AudioAlignmentBatchJobSnapshot, String> {
    let plan = plan_audio_alignment_batch(request)?;
    let permit = acquire_ordinary_alignment_run()?;
    let created = batch_jobs::create_job(
        &plan,
        Some(alignment_diagnostic_log_root(&app)),
        Some(alignment_sensitive_manifest_root(&app)),
    )?;
    let job_id = created.job_id;
    let cancel_flag = created.cancel_flag;
    if let Err(error) = c137_process_attestation::record_blind_batch_started(&job_id) {
        let _ = batch_jobs::remove_job(&job_id);
        return Err(error);
    }
    let worker_job_id = job_id.clone();
    tauri::async_runtime::spawn_blocking(move || {
        let _permit = permit;
        run_audio_alignment_batch_job(worker_job_id, cancel_flag, plan);
    });
    get_audio_alignment_batch_job(job_id)
}

#[tauri::command]
pub fn get_audio_alignment_batch_job(
    job_id: String,
) -> Result<AudioAlignmentBatchJobSnapshot, String> {
    let snapshot = batch_jobs::get_job(&job_id)?;
    if matches!(
        snapshot.status,
        AudioAlignmentJobStatus::Completed
            | AudioAlignmentJobStatus::Failed
            | AudioAlignmentJobStatus::Cancelled
    ) {
        c137_process_attestation::record_blind_batch_terminal(&job_id)?;
    }
    Ok(snapshot)
}

#[tauri::command]
pub fn cancel_audio_alignment_batch_job(
    job_id: String,
) -> Result<AudioAlignmentBatchJobSnapshot, String> {
    batch_jobs::request_cancellation(&job_id)
}

