fn try_v2_visual_fallback(
    request: &AudioAlignmentRequest,
    options: &AudioAlignmentOptions,
    audio_reason: &str,
    mut notes: Vec<String>,
    cancel_flag: Option<&AtomicBool>,
) -> Result<AudioAlignmentProposal, String> {
    benchmark_telemetry::stage("extracting-visual", "执行独立视觉定位回退");
    check_cancelled(cancel_flag)?;
    ensure_alignment_process_supervision_clean()?;
    notes.push(format!("音频主路径已阻断：{audio_reason}"));
    let source_input = match probe_alignment_visual_input(
        &request.source_path,
        "B 站参考",
        request.source_video_stream_index,
        options,
        cancel_flag,
    ) {
        Ok(input) => input,
        Err(error) => {
            propagate_alignment_process_cleanup(&error)?;
            if error == AUDIO_ALIGNMENT_CANCELLED || is_media_identity_guard_error(&error) {
                return Err(error);
            }
            return Ok(report_v2_visual_unavailable_fallback(
                audio_reason,
                &format!("B 站参考视觉不可用：{}", truncate_visual_note(&error)),
                notes,
            ));
        }
    };
    let target_input = match probe_alignment_visual_input(
        &request.complete_path,
        "目标原片",
        request.complete_video_stream_index,
        options,
        cancel_flag,
    ) {
        Ok(input) => input,
        Err(error) => {
            propagate_alignment_process_cleanup(&error)?;
            if error == AUDIO_ALIGNMENT_CANCELLED || is_media_identity_guard_error(&error) {
                return Err(error);
            }
            return Ok(report_v2_visual_unavailable_fallback(
                audio_reason,
                &format!("目标原片视觉不可用：{}", truncate_visual_note(&error)),
                notes,
            ));
        }
    };
    let source_features = match get_v2_visual_features(
        &request.source_path,
        "B 站参考",
        options,
        &source_input,
        cancel_flag,
    ) {
        Ok(features) => features,
        Err(error) => {
            propagate_alignment_process_cleanup(&error)?;
            if error == AUDIO_ALIGNMENT_CANCELLED || is_media_identity_guard_error(&error) {
                return Err(error);
            }
            return Ok(report_v2_visual_unavailable_fallback(
                audio_reason,
                &format!("B 站参考视觉特征不可用：{}", truncate_visual_note(&error)),
                notes,
            ));
        }
    };
    let target_features = match get_v2_visual_features(
        &request.complete_path,
        "目标原片",
        options,
        &target_input,
        cancel_flag,
    ) {
        Ok(features) => features,
        Err(error) => {
            propagate_alignment_process_cleanup(&error)?;
            if error == AUDIO_ALIGNMENT_CANCELLED || is_media_identity_guard_error(&error) {
                return Err(error);
            }
            return Ok(report_v2_visual_unavailable_fallback(
                audio_reason,
                &format!("目标原片视觉特征不可用：{}", truncate_visual_note(&error)),
                notes,
            ));
        }
    };
    let result = match_visual_features_affine(
        source_features.frames(),
        target_features.frames(),
        cancel_flag,
    )?;
    notes.push(format!(
        "独立视觉回退：参考/目标有效帧 {}/{}，外观候选 {}，缓存参考{}、目标{}。",
        result.informative_source_count,
        result.informative_target_count,
        result.candidate_count,
        if source_features.cache_hit() {
            "命中"
        } else {
            "新提取"
        },
        if target_features.cache_hit() {
            "命中"
        } else {
            "新提取"
        },
    ));
    Ok(adjudicate_v2_visual_affine_fallback(
        audio_reason,
        &source_input,
        &target_input,
        source_features.frames(),
        target_features.frames(),
        result,
        notes,
        options,
    ))
}

fn report_v2_visual_unavailable_fallback(
    audio_reason: &str,
    visual_reason: &str,
    notes: Vec<String>,
) -> AudioAlignmentProposal {
    benchmark_telemetry::stage("reporting", "生成视觉回退阻断证据");
    benchmark_telemetry::stage("reporting", "生成阻断型 Alignment V2 复核证据");
    build_v2_visual_unavailable_fallback(V2VisualUnavailableFallbackInput {
        audio_reason: audio_reason.to_string(),
        visual_reason: visual_reason.to_string(),
        diagnostics: notes,
    })
}

#[allow(clippy::too_many_arguments)]
fn adjudicate_v2_visual_affine_fallback(
    audio_reason: &str,
    source_input: &AlignmentVisualInput,
    target_input: &AlignmentVisualInput,
    source_frames: &[VisualFeatureFrame],
    target_frames: &[VisualFeatureFrame],
    result: VisualAffineMatchResult,
    mut diagnostics: Vec<String>,
    options: &AudioAlignmentOptions,
) -> AudioAlignmentProposal {
    benchmark_telemetry::stage("reporting", "生成独立视觉定位复核证据");
    let Some(best) = result.hypotheses.first() else {
        let reason = if result.informative_source_count < ALIGNMENT_V2_VISUAL_MIN_INLIERS
            || result.informative_target_count < ALIGNMENT_V2_VISUAL_MIN_INLIERS
        {
            "画面信息量过低，未达到独立视觉定位的最小有效帧数。"
        } else {
            "视觉外观候选未形成满足 scale 0.94–1.06 的单调仿射假设。"
        };
        return report_v2_visual_unavailable_fallback(audio_reason, reason, diagnostics);
    };
    diagnostics.push(format!(
        "视觉 Top-K：{}。",
        result
            .hypotheses
            .iter()
            .map(|item| format!(
                "scale={:.6},offset={:+},inliers={},coverage={:.3},span={:.3},distance={:.3},score={:.3}",
                item.scale,
                item.offset_ms,
                item.matches.len(),
                item.coverage,
                item.temporal_span_coverage,
                item.mean_distance,
                item.score,
            ))
            .collect::<Vec<_>>()
            .join("；")
    ));
    let interval_ms = estimate_visual_frame_step_ms(source_frames)
        .max(estimate_visual_frame_step_ms(target_frames));
    let full_source_bounds = visual_stream_domain(source_input, source_frames, interval_ms);
    let full_target_bounds = visual_stream_domain(target_input, target_frames, interval_ms);
    let mapped_full_target_start =
        visual_affine_map_time(best, full_source_bounds.0).unwrap_or(u64::MAX);
    let mapped_full_target_end =
        visual_affine_map_time(best, full_source_bounds.1).unwrap_or(u64::MAX);
    let mapping_inside_target = mapped_full_target_start.saturating_add(interval_ms)
        >= full_target_bounds.0
        && mapped_full_target_end <= full_target_bounds.1.saturating_add(interval_ms)
        && mapped_full_target_end > mapped_full_target_start;
    let passes_evidence_gate = best.matches.len() >= ALIGNMENT_V2_VISUAL_MIN_INLIERS
        && best.coverage >= ALIGNMENT_V2_VISUAL_MIN_COVERAGE
        && best.temporal_span_coverage >= ALIGNMENT_V2_VISUAL_MIN_COVERAGE
        && result.top1_top2_margin >= ALIGNMENT_V2_VISUAL_MIN_MARGIN
        && mapping_inside_target;
    let repeated_content_only = result.top1_top2_margin < ALIGNMENT_V2_VISUAL_MIN_MARGIN
        && result.hypotheses.get(1).is_some_and(|alternative| {
            alternative.matches.len() * 4 >= best.matches.len() * 3
                && alternative.offset_ms.abs_diff(best.offset_ms) > interval_ms.saturating_mul(2)
        });
    let (source_start_ms, source_end_ms, target_start_ms, target_end_ms) = if passes_evidence_gate {
        (
            full_source_bounds.0,
            full_source_bounds.1,
            mapped_full_target_start,
            mapped_full_target_end,
        )
    } else {
        visual_observed_bounds(best, interval_ms)
    };
    let mut quality_reasons = vec![
        "视觉回退是稀疏仿射定位，只能确认粗粒度时间关系，不能宣称精确删减边界。".to_string(),
        "真实媒体冻结集和概率校准尚未完成；视觉结果最高只能进入人工复核。".to_string(),
    ];
    if best.coverage < ALIGNMENT_V2_VISUAL_MIN_COVERAGE
        || best.temporal_span_coverage < ALIGNMENT_V2_VISUAL_MIN_COVERAGE
    {
        quality_reasons.push(format!(
            "视觉覆盖不足：有效帧覆盖 {:.3}，时间跨度覆盖 {:.3}。",
            best.coverage, best.temporal_span_coverage
        ));
    }
    if result.top1_top2_margin < ALIGNMENT_V2_VISUAL_MIN_MARGIN {
        quality_reasons.push(format!(
            "重复片头或重复画面仍有竞争位置：Top1/Top2 margin {:.3} 低于 {:.3}。",
            result.top1_top2_margin, ALIGNMENT_V2_VISUAL_MIN_MARGIN
        ));
    }
    if !mapping_inside_target {
        quality_reasons.push("视觉仿射外推超出目标视频展示时间域。".to_string());
    }
    diagnostics.extend(quality_reasons.clone());
    let parameters_hash =
        create_v2_visual_parameters_hash(source_input, target_input, options, interval_ms);
    let selected_reason = format!(
        "音频不可用后，独立视觉选择参考视频流 #{} → 目标视频流 #{}；Top1/Top2 margin {:.3}。",
        source_input.stream.stream_index, target_input.stream.stream_index, result.top1_top2_margin
    );
    build_v2_visual_affine_fallback(V2VisualAffineFallbackInput {
        audio_reason: audio_reason.to_string(),
        diagnostics,
        passes_evidence_gate,
        repeated_content_only,
        source_start_ms,
        source_end_ms,
        target_start_ms,
        target_end_ms,
        coverage: best.coverage,
        temporal_span_coverage: best.temporal_span_coverage,
        top1_top2_margin: result.top1_top2_margin,
        p50_residual_ms: best.p50_residual_ms,
        p95_residual_ms: best.p95_residual_ms,
        max_residual_ms: best.max_residual_ms,
        interval_ms,
        matches: best
            .matches
            .iter()
            .map(|item| V2VisualAffineMatch {
                source_time_ms: item.source_time_ms,
                target_time_ms: item.target_time_ms,
            })
            .collect(),
        hypothesis_count: result.hypotheses.len(),
        informative_source_count: result.informative_source_count,
        informative_target_count: result.informative_target_count,
        candidate_count: result.candidate_count,
        source_stream: v2_video_stream_identity(&source_input.stream),
        target_stream: v2_video_stream_identity(&target_input.stream),
        source_identity: source_input.content_identity.clone(),
        target_identity: target_input.content_identity.clone(),
        feature_version: ALIGNMENT_V2_VISUAL_FEATURE_VERSION,
        parameters_hash,
        selected_track_reason: selected_reason,
        quality_reasons,
    })
}

fn visual_stream_domain(
    input: &AlignmentVisualInput,
    frames: &[VisualFeatureFrame],
    interval_ms: u64,
) -> (u64, u64) {
    let start = input.stream.timeline_offset_ms.max(0) as u64;
    let end = input
        .stream
        .duration_ms
        .map(|duration| start.saturating_add(duration))
        .or(input.media_duration_ms)
        .or_else(|| {
            frames
                .last()
                .map(|frame| frame.time_ms.saturating_add(interval_ms))
        })
        .unwrap_or_else(|| start.saturating_add(interval_ms))
        .max(start.saturating_add(1));
    (start, end)
}

fn visual_affine_map_time(hypothesis: &VisualAffineHypothesis, source_ms: u64) -> Option<u64> {
    let target = hypothesis.scale * source_ms as f64 + hypothesis.offset_ms as f64;
    (target.is_finite() && target >= 0.0 && target <= u64::MAX as f64)
        .then_some(target.round() as u64)
}

fn visual_observed_bounds(
    hypothesis: &VisualAffineHypothesis,
    interval_ms: u64,
) -> (u64, u64, u64, u64) {
    let source_start = hypothesis
        .matches
        .first()
        .map(|item| item.source_time_ms)
        .unwrap_or(0);
    let source_end = hypothesis
        .matches
        .last()
        .map(|item| item.source_time_ms.saturating_add(interval_ms))
        .unwrap_or_else(|| source_start.saturating_add(interval_ms))
        .max(source_start.saturating_add(1));
    let target_start = visual_affine_map_time(hypothesis, source_start).unwrap_or(0);
    let target_end = visual_affine_map_time(hypothesis, source_end)
        .unwrap_or_else(|| target_start.saturating_add(1))
        .max(target_start.saturating_add(1));
    (source_start, source_end, target_start, target_end)
}

fn create_v2_visual_parameters_hash(
    source: &AlignmentVisualInput,
    target: &AlignmentVisualInput,
    options: &AudioAlignmentOptions,
    interval_ms: u64,
) -> String {
    let parameters = format!(
        "engine={ALIGNMENT_V2_ENGINE_VERSION}|feature={ALIGNMENT_V2_VISUAL_FEATURE_VERSION}|interval={interval_ms}|threshold={ALIGNMENT_V2_VISUAL_MATCH_THRESHOLD}|scale=0.94:1.06|ffmpeg={}|source={:?}|target={:?}",
        options.ffmpeg_path,
        (
            source.stream.stream_index,
            source.presentation_origin_ms,
            source.stream.start_time_ms,
            source.stream.timeline_offset_ms,
            source.stream.time_base.as_deref(),
            source.content_identity.as_ref(),
        ),
        (
            target.stream.stream_index,
            target.presentation_origin_ms,
            target.stream.start_time_ms,
            target.stream.timeline_offset_ms,
            target.stream.time_base.as_deref(),
            target.content_identity.as_ref(),
        ),
    );
    let mut hash = 0xcbf2_9ce4_8422_2325u64;
    for byte in parameters.bytes() {
        hash ^= u64::from(byte);
        hash = hash.wrapping_mul(0x1000_0000_01b3);
    }
    format!("fnv1a64:{hash:016x}")
}

fn run_v2_visual_validation(
    request: &AudioAlignmentRequest,
    options: &AudioAlignmentOptions,
    mut proposal: AudioAlignmentProposal,
    cancel_flag: Option<&AtomicBool>,
) -> Result<AudioAlignmentProposal, String> {
    check_cancelled(cancel_flag)?;
    let (expected_source_identity, expected_target_identity) =
        v2_time_map_media_identities_for_visual_validation(&proposal)?;
    let source_input = match probe_alignment_visual_input(
        &request.source_path,
        "B 站参考",
        request.source_video_stream_index,
        options,
        cancel_flag,
    ) {
        Ok(input) => input,
        Err(error) if is_media_identity_guard_error(&error) => return Err(error),
        Err(error) => {
            propagate_alignment_process_cleanup(&error)?;
            return Ok(apply_v2_visual_validation(V2VisualValidationInput {
                proposal,
                source_visual_stream: None,
                target_visual_stream: None,
                assessment: V2VisualValidationAssessment::Unavailable {
                    note: format!("参考视频视觉校验不可用：{}", truncate_visual_note(&error)),
                },
            }));
        }
    };
    let target_input = match probe_alignment_visual_input(
        &request.complete_path,
        "目标原片",
        request.complete_video_stream_index,
        options,
        cancel_flag,
    ) {
        Ok(input) => input,
        Err(error) if is_media_identity_guard_error(&error) => return Err(error),
        Err(error) => {
            propagate_alignment_process_cleanup(&error)?;
            return Ok(apply_v2_visual_validation(V2VisualValidationInput {
                proposal,
                source_visual_stream: None,
                target_visual_stream: None,
                assessment: V2VisualValidationAssessment::Unavailable {
                    note: format!("目标视频视觉校验不可用：{}", truncate_visual_note(&error)),
                },
            }));
        }
    };
    ensure_visual_input_matches_time_map_identity(
        &expected_source_identity,
        source_input.content_identity.as_ref(),
        "参考视频",
    )?;
    ensure_visual_input_matches_time_map_identity(
        &expected_target_identity,
        target_input.content_identity.as_ref(),
        "目标视频",
    )?;
    let source_features = match get_v2_visual_features(
        &request.source_path,
        "B 站参考",
        options,
        &source_input,
        cancel_flag,
    ) {
        Ok(features) => features,
        Err(error) if error == AUDIO_ALIGNMENT_CANCELLED => return Err(error),
        Err(error) if is_media_identity_guard_error(&error) => return Err(error),
        Err(error) => {
            propagate_alignment_process_cleanup(&error)?;
            return Ok(apply_v2_visual_validation(V2VisualValidationInput {
                proposal,
                source_visual_stream: None,
                target_visual_stream: None,
                assessment: V2VisualValidationAssessment::Unavailable {
                    note: format!("参考视频视觉校验提取失败：{}", truncate_visual_note(&error)),
                },
            }));
        }
    };
    let target_features = match get_v2_visual_features(
        &request.complete_path,
        "目标原片",
        options,
        &target_input,
        cancel_flag,
    ) {
        Ok(features) => features,
        Err(error) if error == AUDIO_ALIGNMENT_CANCELLED => return Err(error),
        Err(error) if is_media_identity_guard_error(&error) => return Err(error),
        Err(error) => {
            propagate_alignment_process_cleanup(&error)?;
            return Ok(apply_v2_visual_validation(V2VisualValidationInput {
                proposal,
                source_visual_stream: None,
                target_visual_stream: None,
                assessment: V2VisualValidationAssessment::Unavailable {
                    note: format!("目标视频视觉校验提取失败：{}", truncate_visual_note(&error)),
                },
            }));
        }
    };
    // Cache hits do not run FFmpeg and therefore need their own full-file recheck. Compare to the
    // audio timeMap identities, not merely the newly probed visual inputs, before attaching any
    // visual stream or evidence.
    verify_media_content_identity_after_tool_output(
        &request.source_path,
        Some(&expected_source_identity),
        cancel_flag,
        "视觉证据绑定复核",
    )?;
    verify_media_content_identity_after_tool_output(
        &request.complete_path,
        Some(&expected_target_identity),
        cancel_flag,
        "视觉证据绑定复核",
    )?;
    let source_visual_stream = v2_video_stream_identity(&source_input.stream);
    let target_visual_stream = v2_video_stream_identity(&target_input.stream);
    let Some(time_map) = proposal.time_map.as_ref() else {
        return Ok(apply_v2_visual_validation(V2VisualValidationInput {
            proposal,
            source_visual_stream: Some(source_visual_stream),
            target_visual_stream: Some(target_visual_stream),
            assessment: V2VisualValidationAssessment::Unavailable {
                note: "音频路径没有可供视觉校验的 timeMap。".to_string(),
            },
        }));
    };
    let summary = summarize_v2_visual_time_map_validation(
        source_features.frames(),
        target_features.frames(),
        time_map,
        cancel_flag,
    )?;
    let Some(summary) = summary else {
        return Ok(apply_v2_visual_validation(V2VisualValidationInput {
            proposal,
            source_visual_stream: Some(source_visual_stream),
            target_visual_stream: Some(target_visual_stream),
            assessment: V2VisualValidationAssessment::Unavailable {
                note: "视觉有效帧与音频 matched spans 的交集不足，未改变音频质量等级。".to_string(),
            },
        }));
    };
    let conflict = v2_visual_summary_is_conflict(&summary);
    let local_visual = proposal.evidence_profile.as_mut().map(|profile| {
        enrich_v2_risk_windows_with_visual_support(
            profile,
            source_features.frames(),
            target_features.frames(),
        )
    });
    Ok(apply_v2_visual_validation(V2VisualValidationInput {
        proposal,
        source_visual_stream: Some(source_visual_stream),
        target_visual_stream: Some(target_visual_stream),
        assessment: V2VisualValidationAssessment::Observed {
            observation: summary,
            local_visual,
            conflict,
        },
    }))
}

fn enrich_v2_risk_windows_with_visual_support(
    profile: &mut AlignmentEvidenceProfileDto,
    source_frames: &[VisualFeatureFrame],
    target_frames: &[VisualFeatureFrame],
) -> V2VisualRiskWindowSummary {
    let mut summary = V2VisualRiskWindowSummary::default();
    let source_step_ms = estimate_visual_frame_step_ms(source_frames);
    let target_step_ms = estimate_visual_frame_step_ms(target_frames);
    let max_distance_ms = source_step_ms.max(target_step_ms).saturating_mul(2);
    for sample in &mut profile.samples {
        if sample.axis != "source"
            || (sample.difference_risk < 0.35
                && sample.informativeness >= 0.16
                && sample.dominant_state == "matched")
        {
            continue;
        }
        let Some(counterpart_ms) = sample.counterpart_ms else {
            continue;
        };
        let source_ms = sample
            .start_ms
            .saturating_add(sample.end_ms.saturating_sub(sample.start_ms) / 2);
        let Some(source) = find_nearest_visual_frame_binary(source_frames, source_ms) else {
            continue;
        };
        if source.time_ms.abs_diff(source_ms) > max_distance_ms
            || visual_information_score(source) < ALIGNMENT_V2_VISUAL_MIN_INFORMATION
        {
            continue;
        }
        summary.attempted = summary.attempted.saturating_add(1);
        if let Some(target) = find_nearest_visual_frame_binary(target_frames, counterpart_ms) {
            if target.time_ms.abs_diff(counterpart_ms) <= max_distance_ms
                && visual_information_score(target) >= ALIGNMENT_V2_VISUAL_MIN_INFORMATION
            {
                let distance = get_visual_feature_distance(source, target);
                let support =
                    (1.0 - distance / ALIGNMENT_V2_VISUAL_MATCH_THRESHOLD).clamp(0.0, 1.0);
                sample.visual_support = Some(support);
                if distance <= ALIGNMENT_V2_VISUAL_MATCH_THRESHOLD {
                    summary.supported = summary.supported.saturating_add(1);
                    if sample.dominant_state == "uncertain" {
                        sample.match_probability = sample.match_probability.max(support * 0.8);
                        sample.difference_risk = sample.difference_risk.min(1.0 - support * 0.55);
                        sample.reason_code = "visualLocalizedSupport";
                    }
                } else {
                    summary.conflicting = summary.conflicting.saturating_add(1);
                    sample.difference_risk = sample.difference_risk.max(0.65);
                    sample.reason_code = "visualLocalizedConflict";
                }
            }
        }

        let recovery = find_v2_visual_recovery_anchor(
            sample,
            source_frames,
            target_frames,
            source_step_ms,
            target_step_ms,
        );
        sample.visual_recovery_state = Some(match recovery.state {
            V2VisualRecoverySearchState::Recovered => "recovered",
            V2VisualRecoverySearchState::Ambiguous => "ambiguous",
            V2VisualRecoverySearchState::NotFound => "notFound",
        });
        if let Some(anchor) = recovery.anchor {
            summary.recovered = summary.recovered.saturating_add(1);
            sample.visual_match_ms = Some(anchor.target_time_ms);
            sample.visual_offset_ms = Some(anchor.offset_ms);
            sample.visual_confidence = Some(anchor.confidence);
            sample.visual_margin = Some(anchor.margin);
            sample.visual_support =
                Some(sample.visual_support.unwrap_or(0.0).max(anchor.confidence));
            if sample.dominant_state == "uncertain" {
                sample.match_probability = sample.match_probability.max(anchor.confidence * 0.72);
                sample.difference_risk = sample.difference_risk.min(1.0 - anchor.confidence * 0.45);
                sample.reason_code = "visualAnchorRecovered";
            }
        } else if recovery.state == V2VisualRecoverySearchState::Ambiguous {
            summary.ambiguous = summary.ambiguous.saturating_add(1);
        }
    }
    summary
}

fn find_v2_visual_recovery_anchor(
    sample: &AlignmentEvidenceSampleDto,
    source_frames: &[VisualFeatureFrame],
    target_frames: &[VisualFeatureFrame],
    source_step_ms: u64,
    target_step_ms: u64,
) -> V2VisualRecoverySearch {
    let Some(expected_target_ms) = sample.counterpart_ms else {
        return V2VisualRecoverySearch {
            state: V2VisualRecoverySearchState::NotFound,
            anchor: None,
        };
    };
    let source_center_ms = sample
        .start_ms
        .saturating_add(sample.end_ms.saturating_sub(sample.start_ms) / 2);
    let expected_offset_ms = (expected_target_ms as i128 - source_center_ms as i128)
        .clamp(i64::MIN as i128, i64::MAX as i128) as i64;
    let source_start_ms = sample
        .start_ms
        .saturating_sub(ALIGNMENT_V2_VISUAL_RECOVERY_CONTEXT_MS);
    let source_end_ms = sample
        .end_ms
        .saturating_add(ALIGNMENT_V2_VISUAL_RECOVERY_CONTEXT_MS);
    let mut observations = Vec::new();
    let mut saw_competing_candidate = false;
    for source in source_frames.iter().filter(|frame| {
        frame.time_ms >= source_start_ms
            && frame.time_ms <= source_end_ms
            && visual_information_score(frame) >= ALIGNMENT_V2_VISUAL_MIN_INFORMATION
    }) {
        let predicted_target_ms = add_signed_milliseconds(
            source.time_ms,
            expected_offset_ms,
            target_frames
                .last()
                .map(|frame| frame.time_ms)
                .unwrap_or(u64::MAX),
        );
        let search_start_ms =
            predicted_target_ms.saturating_sub(ALIGNMENT_V2_VISUAL_RECOVERY_SEARCH_RADIUS_MS);
        let search_end_ms =
            predicted_target_ms.saturating_add(ALIGNMENT_V2_VISUAL_RECOVERY_SEARCH_RADIUS_MS);
        let mut candidates = target_frames
            .iter()
            .filter(|frame| {
                frame.time_ms >= search_start_ms
                    && frame.time_ms <= search_end_ms
                    && visual_information_score(frame) >= ALIGNMENT_V2_VISUAL_MIN_INFORMATION
            })
            .map(|target| (target, get_visual_feature_distance(source, target)))
            .collect::<Vec<_>>();
        candidates.sort_by(|left, right| {
            left.1
                .total_cmp(&right.1)
                .then_with(|| left.0.time_ms.cmp(&right.0.time_ms))
        });
        let Some((best, best_distance)) = candidates.first().copied() else {
            continue;
        };
        if best_distance > ALIGNMENT_V2_VISUAL_MATCH_THRESHOLD {
            continue;
        }
        let same_location_radius_ms = target_step_ms.max(1).saturating_mul(2);
        let second_distance = candidates
            .iter()
            .find(|(candidate, _)| {
                candidate.time_ms.abs_diff(best.time_ms) > same_location_radius_ms
            })
            .map(|(_, distance)| *distance)
            .unwrap_or(ALIGNMENT_V2_VISUAL_MATCH_THRESHOLD * 2.0);
        let margin = ((second_distance - best_distance) / ALIGNMENT_V2_VISUAL_MATCH_THRESHOLD)
            .clamp(0.0, 1.0);
        if margin < ALIGNMENT_V2_VISUAL_MIN_MARGIN {
            saw_competing_candidate = true;
            continue;
        }
        observations.push(V2VisualRecoveryObservation {
            source_time_ms: source.time_ms,
            offset_ms: (best.time_ms as i128 - source.time_ms as i128)
                .clamp(i64::MIN as i128, i64::MAX as i128) as i64,
            distance: best_distance,
            margin,
        });
    }
    if observations.len() < ALIGNMENT_V2_VISUAL_RECOVERY_MIN_OBSERVATIONS {
        return V2VisualRecoverySearch {
            state: if saw_competing_candidate {
                V2VisualRecoverySearchState::Ambiguous
            } else {
                V2VisualRecoverySearchState::NotFound
            },
            anchor: None,
        };
    }
    let offset_tolerance_ms = source_step_ms
        .max(target_step_ms)
        .saturating_mul(2)
        .max(2_000);
    let mut best_cluster = Vec::new();
    for seed in &observations {
        let cluster = observations
            .iter()
            .filter(|candidate| seed.offset_ms.abs_diff(candidate.offset_ms) <= offset_tolerance_ms)
            .cloned()
            .collect::<Vec<_>>();
        let cluster_better = cluster.len() > best_cluster.len()
            || (cluster.len() == best_cluster.len()
                && visual_recovery_mean_distance(&cluster)
                    < visual_recovery_mean_distance(&best_cluster));
        if cluster_better {
            best_cluster = cluster;
        }
    }
    let required_consensus =
        ((observations.len() as f64 * ALIGNMENT_V2_VISUAL_RECOVERY_MIN_CONSENSUS).ceil() as usize)
            .max(ALIGNMENT_V2_VISUAL_RECOVERY_MIN_OBSERVATIONS);
    if best_cluster.len() < required_consensus {
        return V2VisualRecoverySearch {
            state: V2VisualRecoverySearchState::Ambiguous,
            anchor: None,
        };
    }
    let source_span_ms = best_cluster
        .iter()
        .map(|item| item.source_time_ms)
        .min()
        .zip(best_cluster.iter().map(|item| item.source_time_ms).max())
        .map(|(start, end)| end.saturating_sub(start))
        .unwrap_or(0);
    if source_span_ms < source_step_ms.max(1) {
        return V2VisualRecoverySearch {
            state: V2VisualRecoverySearchState::Ambiguous,
            anchor: None,
        };
    }
    let offset_ms = median_offset(best_cluster.iter().map(|item| item.offset_ms).collect());
    let target_time_ms = add_signed_milliseconds(
        source_center_ms,
        offset_ms,
        target_frames
            .last()
            .map(|frame| frame.time_ms)
            .unwrap_or(u64::MAX),
    );
    let mean_distance = visual_recovery_mean_distance(&best_cluster);
    let mut margins = best_cluster
        .iter()
        .map(|item| item.margin)
        .collect::<Vec<_>>();
    margins.sort_by(f64::total_cmp);
    let margin = margins.get(margins.len() / 2).copied().unwrap_or(0.0);
    let observation_factor = (best_cluster.len() as f64
        / ALIGNMENT_V2_VISUAL_RECOVERY_MIN_OBSERVATIONS as f64)
        .clamp(0.0, 1.0);
    let confidence = ((1.0 - mean_distance / ALIGNMENT_V2_VISUAL_MATCH_THRESHOLD)
        * (0.6 + margin * 0.4)
        * observation_factor)
        .clamp(0.0, 1.0);
    V2VisualRecoverySearch {
        state: V2VisualRecoverySearchState::Recovered,
        anchor: Some(V2VisualRecoveryAnchor {
            target_time_ms,
            offset_ms,
            confidence,
            margin,
        }),
    }
}

fn visual_recovery_mean_distance(observations: &[V2VisualRecoveryObservation]) -> f64 {
    if observations.is_empty() {
        return f64::INFINITY;
    }
    observations.iter().map(|item| item.distance).sum::<f64>() / observations.len() as f64
}

fn v2_time_map_media_identities_for_visual_validation(
    proposal: &AudioAlignmentProposal,
) -> Result<(MediaContentIdentity, MediaContentIdentity), String> {
    let time_map = proposal.time_map.as_ref().ok_or_else(|| {
        "blocked:media-identity-missing：音频路径没有可绑定视觉证据的 timeMap。".to_string()
    })?;
    let source = require_full_file_media_content_identity(time_map.source_identity.as_ref())?;
    let target = require_full_file_media_content_identity(time_map.target_identity.as_ref())?;
    Ok((source.clone(), target.clone()))
}

fn ensure_visual_input_matches_time_map_identity(
    expected: &MediaContentIdentity,
    observed: Option<&MediaContentIdentity>,
    role: &str,
) -> Result<(), String> {
    let observed = require_full_file_media_content_identity(observed)?;
    if observed != expected {
        return Err(format!(
            "blocked:media-identity-changed：{role}视觉证据与音频 timeMap 的全文件身份不一致；拒绝混合证据。"
        ));
    }
    Ok(())
}

fn is_media_identity_guard_error(error: &str) -> bool {
    error.starts_with("blocked:media-identity-")
}

fn v2_visual_summary_is_conflict(summary: &V2VisualValidationObservation) -> bool {
    let support_ratio = summary.supported_observations as f64 / summary.observations.max(1) as f64;
    summary.observations >= ALIGNMENT_V2_VISUAL_MIN_INLIERS
        && support_ratio < 0.25
        && summary.mean_distance > ALIGNMENT_V2_VISUAL_MATCH_THRESHOLD
}

fn summarize_v2_visual_time_map_validation(
    source_frames: &[VisualFeatureFrame],
    target_frames: &[VisualFeatureFrame],
    time_map: &AudioAlignmentTimeMapDto,
    cancel_flag: Option<&AtomicBool>,
) -> Result<Option<V2VisualValidationObservation>, String> {
    let source_indices = uniformly_sample_informative_visual_indices(source_frames);
    if source_indices.is_empty() || target_frames.is_empty() {
        return Ok(None);
    }
    let max_distance_ms = estimate_visual_frame_step_ms(source_frames)
        .max(estimate_visual_frame_step_ms(target_frames))
        .saturating_mul(2);
    let mut observations = 0usize;
    let mut supported_observations = 0usize;
    let mut total_distance = 0.0;
    for (position, source_index) in source_indices.into_iter().enumerate() {
        if position % 32 == 0 {
            check_cancelled(cancel_flag)?;
        }
        let source = &source_frames[source_index];
        let Some(mapped_target_ms) = map_source_time_through_v2_time_map(time_map, source.time_ms)
        else {
            continue;
        };
        let Some(target) = find_nearest_visual_frame_binary(target_frames, mapped_target_ms) else {
            continue;
        };
        if target.time_ms.abs_diff(mapped_target_ms) > max_distance_ms
            || visual_information_score(target) < ALIGNMENT_V2_VISUAL_MIN_INFORMATION
        {
            continue;
        }
        let distance = get_visual_feature_distance(source, target);
        observations += 1;
        total_distance += distance;
        if distance <= ALIGNMENT_V2_VISUAL_MATCH_THRESHOLD {
            supported_observations += 1;
        }
    }
    if observations == 0 {
        return Ok(None);
    }
    Ok(Some(V2VisualValidationObservation {
        observations,
        supported_observations,
        mean_distance: total_distance / observations as f64,
    }))
}

fn map_source_time_through_v2_time_map(
    time_map: &AudioAlignmentTimeMapDto,
    source_ms: u64,
) -> Option<u64> {
    let span = time_map
        .spans
        .iter()
        .enumerate()
        .find_map(|(index, span)| {
            let contains = source_ms >= span.source_start_ms
                && (source_ms < span.source_end_ms
                    || (index + 1 == time_map.spans.len() && source_ms == span.source_end_ms));
            (contains && span.kind == AudioTimeMapSpanKind::Matched).then_some(span)
        })?;
    let source_duration = span.source_end_ms.checked_sub(span.source_start_ms)?;
    let target_duration = span.target_end_ms.checked_sub(span.target_start_ms)?;
    if source_duration == 0 {
        return None;
    }
    let relative = source_ms.saturating_sub(span.source_start_ms) as f64 / source_duration as f64;
    Some((span.target_start_ms as f64 + relative * target_duration as f64).round() as u64)
}

fn find_nearest_visual_frame_binary(
    frames: &[VisualFeatureFrame],
    time_ms: u64,
) -> Option<&VisualFeatureFrame> {
    if frames.is_empty() {
        return None;
    }
    let insertion = frames.partition_point(|frame| frame.time_ms < time_ms);
    match (insertion.checked_sub(1), frames.get(insertion)) {
        (Some(before), Some(after)) => {
            let before = &frames[before];
            if before.time_ms.abs_diff(time_ms) <= after.time_ms.abs_diff(time_ms) {
                Some(before)
            } else {
                Some(after)
            }
        }
        (Some(before), None) => frames.get(before),
        (None, Some(after)) => Some(after),
        (None, None) => None,
    }
}

fn run_audio_alignment_job(
    job_id: String,
    cancel_flag: Arc<AtomicBool>,
    request: AudioAlignmentRequest,
    spectral_backend_request: SpectralBackendRequest,
) {
    let mut update = |progress: f64, message: &str| {
        if cancel_flag.load(Ordering::Relaxed) {
            return Err(AUDIO_ALIGNMENT_CANCELLED.to_string());
        }
        jobs::update_job(
            &job_id,
            AudioAlignmentJobStatus::Running,
            progress,
            message,
            None,
            None,
        )
    };
    let result = align_audio_files_with_progress_and_spectral_backend_request(
        request,
        spectral_backend_request,
        &mut update,
        Some(cancel_flag.as_ref()),
    );
    if cancel_flag.load(Ordering::Relaxed) {
        let _ = jobs::update_job(
            &job_id,
            AudioAlignmentJobStatus::Cancelled,
            1.0,
            AUDIO_ALIGNMENT_CANCELLED,
            None,
            None,
        );
        return;
    }
    match result {
        Ok(proposal) => {
            let _ = jobs::update_job(
                &job_id,
                AudioAlignmentJobStatus::Completed,
                1.0,
                "本地对齐完成。",
                Some(proposal),
                None,
            );
        }
        Err(error) => {
            let status = if error == AUDIO_ALIGNMENT_CANCELLED {
                AudioAlignmentJobStatus::Cancelled
            } else {
                AudioAlignmentJobStatus::Failed
            };
            let _ = jobs::update_job(&job_id, status, 1.0, &error, None, Some(error.clone()));
        }
    }
}

fn plan_audio_alignment_batch(
    request: AudioAlignmentBatchRequest,
) -> Result<PlannedAudioAlignmentBatch, String> {
    if request.schema_version != AUDIO_ALIGNMENT_BATCH_SCHEMA_VERSION {
        return Err(format!(
            "批量音频对齐 schemaVersion 必须为 {AUDIO_ALIGNMENT_BATCH_SCHEMA_VERSION}。"
        ));
    }
    if request.localization_mode != Some(true) {
        return Err(
            "批量音频对齐只接受显式 localizationMode=true 的 Alignment V2 请求；旧逐 pair 引擎不再通过公共 batch API 静默启用。"
                .to_string(),
        );
    }
    validate_audio_alignment_batch_side_count("参考素材", request.sources.len())?;
    validate_audio_alignment_batch_side_count("目标原片", request.targets.len())?;
    let pairing_mode = if request.pairs.is_some() {
        AudioAlignmentBatchPairingMode::Explicit
    } else {
        AudioAlignmentBatchPairingMode::FullCartesian
    };
    let pair_count = if let Some(pairs) = &request.pairs {
        if pairs.is_empty() {
            return Err("显式批量 pair 列表不能为空。".to_string());
        }
        pairs.len()
    } else {
        request
            .sources
            .len()
            .checked_mul(request.targets.len())
            .ok_or_else(|| "批量音频对齐 pair 数溢出。".to_string())?
    };
    if pair_count > MAX_AUDIO_ALIGNMENT_BATCH_PAIRS {
        return Err(format!(
            "批量音频对齐一次最多允许 {MAX_AUDIO_ALIGNMENT_BATCH_PAIRS} 个 pair；请缩小选择范围。"
        ));
    }
    if request.max_cells == Some(0) {
        return Err("批量音频对齐 maxCells 必须大于 0。".to_string());
    }

    let mut media_ids = HashSet::new();
    let sources = request
        .sources
        .iter()
        .map(|media| normalize_audio_alignment_batch_media(media, &mut media_ids))
        .collect::<Result<Vec<_>, _>>()?;
    let targets = request
        .targets
        .iter()
        .map(|media| normalize_audio_alignment_batch_media(media, &mut media_ids))
        .collect::<Result<Vec<_>, _>>()?;
    let source_media_ids = sources
        .iter()
        .map(|media| media.media_id.clone())
        .collect::<Vec<_>>();
    let target_media_ids = targets
        .iter()
        .map(|media| media.media_id.clone())
        .collect::<Vec<_>>();

    let mut media = sources
        .iter()
        .map(|item| PlannedAudioAlignmentBatchMedia {
            media_id: item.media_id.clone(),
            path: item.path.clone(),
            requested_audio_stream_index: item.audio_stream_index,
            requested_video_stream_index: item.video_stream_index,
            role: "sourceReference",
            role_label: "B 站参考",
        })
        .collect::<Vec<_>>();
    let target_media_offset = media.len();
    media.extend(targets.iter().map(|item| PlannedAudioAlignmentBatchMedia {
        media_id: item.media_id.clone(),
        path: item.path.clone(),
        requested_audio_stream_index: item.audio_stream_index,
        requested_video_stream_index: item.video_stream_index,
        role: "targetOriginal",
        role_label: "目标原片",
    }));
    let mut version_reuse_groups = normalize_audio_alignment_batch_version_reuse_groups(
        &request.version_reuse_groups,
        &sources,
        &targets,
        target_media_offset,
    )?;

    let mut pairs = Vec::with_capacity(pair_count);
    if let Some(pair_selection) = &request.pairs {
        let sources_by_id = sources
            .iter()
            .enumerate()
            .map(|(index, media)| (media.media_id.as_str(), (index, media)))
            .collect::<HashMap<_, _>>();
        let targets_by_id = targets
            .iter()
            .enumerate()
            .map(|(index, media)| {
                (
                    media.media_id.as_str(),
                    (target_media_offset.saturating_add(index), media),
                )
            })
            .collect::<HashMap<_, _>>();
        let mut selected_pairs = HashSet::new();
        for selected in pair_selection {
            let source_id = selected.source_media_id.trim();
            let target_id = selected.target_media_id.trim();
            let Some((source_media_index, source)) = sources_by_id.get(source_id).copied() else {
                return Err("显式 pair 引用了不存在的 sourceMediaId。".to_string());
            };
            let Some((target_media_index, target)) = targets_by_id.get(target_id).copied() else {
                return Err("显式 pair 引用了不存在的 targetMediaId。".to_string());
            };
            if !selected_pairs.insert((source_id.to_string(), target_id.to_string())) {
                return Err("显式批量 pair 不允许重复。".to_string());
            }
            pairs.push(create_planned_audio_alignment_batch_pair(
                pairs.len(),
                pairs.len() + 1,
                source_media_index,
                target_media_index,
                source,
                target,
                &request,
            ));
        }
    } else {
        for (source_media_index, source) in sources.iter().enumerate() {
            for (target_index, target) in targets.iter().enumerate() {
                pairs.push(create_planned_audio_alignment_batch_pair(
                    pairs.len(),
                    pairs.len() + 1,
                    source_media_index,
                    target_media_offset.saturating_add(target_index),
                    source,
                    target,
                    &request,
                ));
            }
        }
    }
    // Explicit pair lists may mention only a subset of the supplied media. Keep the plan's media
    // table distinct and compact so the worker never hashes, probes or decodes an unreferenced
    // local file merely because it appeared in the request envelope.
    let referenced_media = pairs
        .iter()
        .flat_map(|pair| [pair.source_media_index, pair.target_media_index])
        .collect::<HashSet<_>>();
    let mut media_index_remap = vec![usize::MAX; media.len()];
    let mut compact_media = Vec::with_capacity(referenced_media.len());
    for (old_index, item) in media.into_iter().enumerate() {
        if referenced_media.contains(&old_index) {
            media_index_remap[old_index] = compact_media.len();
            compact_media.push(item);
        }
    }
    for pair in &mut pairs {
        pair.source_media_index = media_index_remap[pair.source_media_index];
        pair.target_media_index = media_index_remap[pair.target_media_index];
        pair.source_physical_media_index = pair.source_media_index;
        pair.target_physical_media_index = pair.target_media_index;
        debug_assert_ne!(pair.source_media_index, usize::MAX);
        debug_assert_ne!(pair.target_media_index, usize::MAX);
    }
    for group in &mut version_reuse_groups {
        for media_index in &mut group.media_indices {
            let remapped = media_index_remap[*media_index];
            if remapped == usize::MAX {
                return Err(format!(
                    "版本复用组 {} 包含未被显式 pair 使用的媒体；请只为本批次实际分析的素材分组。",
                    group.snapshot.group_id
                ));
            }
            *media_index = remapped;
        }
    }
    let mut source_group_by_media = HashMap::<usize, u32>::new();
    let mut target_group_by_media = HashMap::<usize, u32>::new();
    for group in &version_reuse_groups {
        let target = match group.snapshot.side {
            AudioAlignmentBatchVersionGroupSide::Source => &mut source_group_by_media,
            AudioAlignmentBatchVersionGroupSide::Target => &mut target_group_by_media,
        };
        for media_index in &group.media_indices {
            target.insert(*media_index, group.snapshot.group_ordinal);
        }
    }
    for pair in &mut pairs {
        pair.source_axis_reuse_group_ordinal =
            target_group_by_media.get(&pair.target_media_index).copied();
        pair.target_axis_reuse_group_ordinal =
            source_group_by_media.get(&pair.source_media_index).copied();
    }
    if pairing_mode == AudioAlignmentBatchPairingMode::Explicit {
        let first_automatic_group_ordinal = version_reuse_groups
            .iter()
            .map(|group| group.snapshot.group_ordinal)
            .max()
            .unwrap_or(0)
            .checked_add(1)
            .ok_or_else(|| "显式 many-to-one 复用组 ordinal 溢出。".to_string())?;
        let relations = pairs
            .iter()
            .map(|pair| ExplicitRelationAxis {
                source_media_index: pair.source_physical_media_index,
                target_media_index: pair.target_physical_media_index,
            })
            .collect::<Vec<_>>();
        let automatic_groups =
            explicit_many_to_one_target_reuse_groups(&relations, first_automatic_group_ordinal)?;
        for (pair, automatic_group) in pairs.iter_mut().zip(automatic_groups) {
            if automatic_group.is_some() {
                // Explicit relations are assertions that each distinct reference should be
                // evaluated against this original. Reusing an overlapping original interval is
                // therefore legal; source-axis conflicts and pair-local evidence still prevent
                // one physical reference range from being consumed inconsistently.
                pair.target_axis_reuse_group_ordinal = automatic_group;
            }
        }
    }
    let media = compact_media;
    let first = pairs
        .first()
        .ok_or_else(|| "批量音频对齐没有可执行 pair。".to_string())?;
    // Resolve the request-local backend policy exactly once before the worker starts. The batch
    // carries this immutable capability snapshot so later media/pair workers never re-read the
    // process environment or silently change policy mid-run.
    let spectral_backend_request = create_options(&first.request)?.spectral_backend_request;
    Ok(PlannedAudioAlignmentBatch {
        pairing_mode,
        source_media_ids,
        target_media_ids,
        version_reuse_groups,
        media,
        pairs,
        spectral_backend_request,
    })
}

fn create_planned_audio_alignment_batch_pair(
    pair_index: usize,
    pair_ordinal: usize,
    source_media_index: usize,
    target_media_index: usize,
    source: &AudioAlignmentBatchMediaRequest,
    target: &AudioAlignmentBatchMediaRequest,
    batch: &AudioAlignmentBatchRequest,
) -> PlannedAudioAlignmentBatchPair {
    PlannedAudioAlignmentBatchPair {
        pair_index,
        pair_ordinal,
        source_media_id: source.media_id.clone(),
        target_media_id: target.media_id.clone(),
        source_media_index,
        target_media_index,
        source_physical_media_index: source_media_index,
        target_physical_media_index: target_media_index,
        source_axis_reuse_group_ordinal: None,
        target_axis_reuse_group_ordinal: None,
        relation_ranking: AudioAlignmentBatchRelationRankingSnapshot::pending(),
        global_selection: AudioAlignmentBatchGlobalSelectionSnapshot::pending(),
        request: AudioAlignmentRequest {
            algorithm: None,
            complete_path: target.path.clone(),
            source_path: source.path.clone(),
            ffmpeg_path: batch.ffmpeg_path.clone(),
            ffprobe_path: batch.ffprobe_path.clone(),
            complete_audio_stream_index: target.audio_stream_index,
            source_audio_stream_index: source.audio_stream_index,
            complete_video_stream_index: target.video_stream_index,
            source_video_stream_index: source.video_stream_index,
            spectral_backend: batch.spectral_backend,
            sample_rate: batch.sample_rate,
            window_ms: batch.window_ms,
            match_threshold: batch.match_threshold,
            min_gap_ms: batch.min_gap_ms,
            max_cells: batch.max_cells,
            enable_visual_evidence: batch.enable_visual_evidence,
            visual_sample_interval_ms: batch.visual_sample_interval_ms,
            localization_mode: batch.localization_mode,
        },
    }
}

fn normalize_audio_alignment_batch_version_reuse_groups(
    groups: &[AudioAlignmentBatchVersionReuseGroupRequest],
    sources: &[AudioAlignmentBatchMediaRequest],
    targets: &[AudioAlignmentBatchMediaRequest],
    target_media_offset: usize,
) -> Result<Vec<PlannedAudioAlignmentBatchVersionReuseGroup>, String> {
    let source_indices = sources
        .iter()
        .enumerate()
        .map(|(index, media)| (media.media_id.as_str(), index))
        .collect::<HashMap<_, _>>();
    let target_indices = targets
        .iter()
        .enumerate()
        .map(|(index, media)| {
            (
                media.media_id.as_str(),
                target_media_offset.saturating_add(index),
            )
        })
        .collect::<HashMap<_, _>>();
    let mut seen_group_ids = HashSet::<String>::new();
    let mut grouped_media = HashSet::<(u8, String)>::new();
    let mut normalized = Vec::<(
        AudioAlignmentBatchVersionGroupSide,
        String,
        Vec<String>,
        Vec<usize>,
    )>::new();
    for group in groups {
        let group_id = group.group_id.trim();
        if group_id.is_empty()
            || group_id.len() > MAX_AUDIO_ALIGNMENT_BATCH_VERSION_GROUP_ID_BYTES
            || group_id.chars().any(char::is_control)
            || !group_id
                .chars()
                .all(|character| character.is_ascii_alphanumeric() || "._:-".contains(character))
        {
            return Err(
                "版本复用 groupId 必须是最多 160 bytes 的 ASCII 字母数字/._:- 标识。".to_string(),
            );
        }
        if !seen_group_ids.insert(group_id.to_string()) {
            return Err("版本复用 groupId 必须全局唯一。".to_string());
        }
        if group.media_ids.len() < 2 {
            return Err("版本复用组至少需要两个不同媒体。".to_string());
        }
        let (side_order, indices) = match group.side {
            AudioAlignmentBatchVersionGroupSide::Source => (0_u8, &source_indices),
            AudioAlignmentBatchVersionGroupSide::Target => (1_u8, &target_indices),
        };
        let mut members = Vec::<(usize, String)>::with_capacity(group.media_ids.len());
        let mut seen_members = HashSet::<String>::new();
        for media_id in &group.media_ids {
            let media_id = media_id.trim();
            let Some(media_index) = indices.get(media_id).copied() else {
                return Err(format!(
                    "版本复用组 {group_id} 引用了错误侧或不存在的 mediaId。"
                ));
            };
            if !seen_members.insert(media_id.to_string()) {
                return Err(format!("版本复用组 {group_id} 包含重复 mediaId。"));
            }
            if !grouped_media.insert((side_order, media_id.to_string())) {
                return Err(format!(
                    "媒体 {media_id} 不能同时属于同一侧的多个版本复用组。"
                ));
            }
            members.push((media_index, media_id.to_string()));
        }
        members.sort_by_key(|(index, _)| *index);
        normalized.push((
            group.side,
            group_id.to_string(),
            members
                .iter()
                .map(|(_, media_id)| media_id.clone())
                .collect(),
            members.into_iter().map(|(index, _)| index).collect(),
        ));
    }
    normalized.sort_by(|left, right| {
        let side_order = |side: AudioAlignmentBatchVersionGroupSide| match side {
            AudioAlignmentBatchVersionGroupSide::Source => 0_u8,
            AudioAlignmentBatchVersionGroupSide::Target => 1_u8,
        };
        side_order(left.0)
            .cmp(&side_order(right.0))
            .then_with(|| left.1.cmp(&right.1))
    });
    normalized
        .into_iter()
        .enumerate()
        .map(|(index, (side, group_id, media_ids, media_indices))| {
            Ok(PlannedAudioAlignmentBatchVersionReuseGroup {
                snapshot: AudioAlignmentBatchVersionReuseGroupSnapshot {
                    group_ordinal: u32::try_from(index + 1)
                        .map_err(|_| "版本复用组序号无法表示为 u32。".to_string())?,
                    group_id,
                    side,
                    media_ids,
                },
                media_indices,
            })
        })
        .collect()
}

fn validate_audio_alignment_batch_side_count(label: &str, count: usize) -> Result<(), String> {
    if count == 0 || count > MAX_AUDIO_ALIGNMENT_BATCH_MEDIA_PER_SIDE {
        return Err(format!(
            "{label}数量必须位于 1–{MAX_AUDIO_ALIGNMENT_BATCH_MEDIA_PER_SIDE}。"
        ));
    }
    Ok(())
}

fn normalize_audio_alignment_batch_media(
    media: &AudioAlignmentBatchMediaRequest,
    media_ids: &mut HashSet<String>,
) -> Result<AudioAlignmentBatchMediaRequest, String> {
    let media_id = media.media_id.trim();
    if media_id.is_empty()
        || media_id.len() > MAX_AUDIO_ALIGNMENT_BATCH_MEDIA_ID_BYTES
        || media_id.chars().any(char::is_control)
        || media_id.contains(['/', '\\'])
    {
        return Err("批量音频对齐 mediaId 必须是无路径分隔符的非空有界标识。".to_string());
    }
    if !media_ids.insert(media_id.to_string()) {
        return Err("批量音频对齐 mediaId 必须在两侧素材中全局唯一。".to_string());
    }
    let path = media.path.trim();
    if path.is_empty() || is_remote_media_input(path) {
        return Err("批量音频对齐只接受非空本地媒体路径。".to_string());
    }
    Ok(AudioAlignmentBatchMediaRequest {
        media_id: media_id.to_string(),
        path: path.to_string(),
        audio_stream_index: media.audio_stream_index,
        video_stream_index: media.video_stream_index,
    })
}

