fn persistent_evidence_profile_summary(
    profile: &AlignmentEvidenceProfileDto,
) -> AudioAlignmentPersistentEvidenceProfileSummary {
    let count = |state: &str| {
        profile
            .samples
            .iter()
            .filter(|sample| sample.state == state)
            .count()
    };
    let largest_offset_step_ms = ["source", "target"]
        .into_iter()
        .filter_map(|axis| {
            let offsets = profile
                .samples
                .iter()
                .filter(|sample| sample.axis == axis)
                .filter_map(|sample| sample.offset_ms)
                .collect::<Vec<_>>();
            offsets
                .windows(2)
                .map(|window| window[1].saturating_sub(window[0]))
                .max_by_key(|delta| delta.unsigned_abs())
        })
        .max_by_key(|delta| delta.unsigned_abs());
    AudioAlignmentPersistentEvidenceProfileSummary {
        version: profile.version,
        window_ms: profile.window_ms,
        sample_count: profile.samples.len(),
        supported_count: count("supported"),
        weak_count: count("weak"),
        conflicting_count: count("conflicting"),
        no_evidence_count: count("noEvidence"),
        source_only_count: count("sourceOnly"),
        target_only_count: count("targetOnly"),
        low_information_count: profile
            .samples
            .iter()
            .filter(|sample| sample.informativeness < 0.16)
            .count(),
        maximum_difference_risk: profile
            .samples
            .iter()
            .map(|sample| sample.difference_risk)
            .fold(0.0, f64::max),
        largest_offset_step_ms,
        visual_supported_window_count: profile
            .samples
            .iter()
            .filter(|sample| sample.visual_support.is_some_and(|support| support >= 0.5))
            .count(),
        visual_conflicting_window_count: profile
            .samples
            .iter()
            .filter(|sample| sample.visual_support.is_some_and(|support| support < 0.2))
            .count(),
        visual_recovered_anchor_count: profile
            .samples
            .iter()
            .filter(|sample| sample.visual_recovery_state == Some("recovered"))
            .count(),
        visual_ambiguous_window_count: profile
            .samples
            .iter()
            .filter(|sample| sample.visual_recovery_state == Some("ambiguous"))
            .count(),
    }
}

fn persistent_pair_result_detail(
    pair: &AudioAlignmentBatchPairSnapshot,
) -> AudioAlignmentPersistentPairResultDetail {
    let proposal = pair.proposal.as_ref();
    let time_map = proposal.and_then(|proposal| proposal.time_map.as_ref());
    let execution = pair.fine_execution_evidence.as_ref();
    AudioAlignmentPersistentPairResultDetail {
        detail_version: ALIGNMENT_PERSISTENT_DETAIL_VERSION,
        detail_type: "pairResult",
        pair_ordinal: pair.pair_ordinal,
        status: pair.status,
        global_selection_state: pair.global_selection.state,
        selected_rank: pair.global_selection.selected_rank,
        decision_rank: pair.global_selection.decision_rank,
        candidate_count: pair.global_selection.candidate_count,
        fine_candidate_id: execution.map(|evidence| evidence.candidate_id),
        selected_member_rank: execution.map(|evidence| evidence.selected_member_rank),
        source_stream_index: time_map
            .and_then(|time_map| time_map.source_stream.as_ref())
            .map(|stream| stream.index)
            .or_else(|| execution.map(|evidence| evidence.source_stream_index)),
        target_stream_index: time_map
            .and_then(|time_map| time_map.target_stream.as_ref())
            .map(|stream| stream.index)
            .or_else(|| execution.map(|evidence| evidence.target_stream_index)),
        confidence: proposal.map(|proposal| proposal.confidence),
        time_map_quality: time_map.map(|time_map| time_map.quality.level),
        time_map_coverage: time_map.and_then(|time_map| time_map.quality.coverage),
        time_map_p95_residual_ms: time_map.and_then(|time_map| time_map.quality.p95_residual_ms),
        visual_anchor_count: time_map.map(|time_map| time_map.evidence.visual_anchor_count),
        spans: time_map
            .map(|time_map| {
                time_map
                    .spans
                    .iter()
                    .map(|span| AudioAlignmentPersistentSpanSummary {
                        kind: span.kind,
                        source_start_ms: span.source_start_ms,
                        source_end_ms: span.source_end_ms,
                        target_start_ms: span.target_start_ms,
                        target_end_ms: span.target_end_ms,
                        quality_level: span.quality.level,
                        probability: span.quality.probability,
                        anchor_count: span.quality.anchor_count,
                        held_out_anchor_count: span.quality.held_out_anchor_count,
                        p95_residual_ms: span.quality.p95_residual_ms,
                        start_boundary: persistent_boundary_summary(&span.boundaries.start),
                        end_boundary: persistent_boundary_summary(&span.boundaries.end),
                    })
                    .collect()
            })
            .unwrap_or_default(),
        evidence_profile: proposal
            .and_then(|proposal| proposal.evidence_profile.as_ref())
            .map(persistent_evidence_profile_summary),
        error_category: pair.error.as_deref().map(persistent_error_category),
    }
}

