    fn frames(values: &[f64]) -> Vec<AudioFeatureFrame> {
        values
            .iter()
            .enumerate()
            .map(|(index, value)| AudioFeatureFrame {
                time_ms: index as u64 * 10_000,
                values: vec![*value],
            })
            .collect()
    }

    fn pattern_frames(count: usize) -> Vec<AudioFeatureFrame> {
        (0..count)
            .map(|index| AudioFeatureFrame {
                time_ms: index as u64 * 1_000,
                values: vec![
                    0.5 + (index as f64 * 0.37).sin() * 0.25,
                    0.5 + (index as f64 * 0.19).cos() * 0.2,
                    0.5 + (index as f64 * 0.11 + 0.4).sin() * 0.18,
                ],
            })
            .collect()
    }

    fn v2_labeled_features(labels: &[usize], start_ms: i64, hop_ms: i64) -> Vec<FineFeatureFrame> {
        labels
            .iter()
            .enumerate()
            .map(|(index, label)| {
                let mut values = vec![0.0f32; 32];
                values[*label] = 1.0;
                let presentation_time_ms = start_ms + index as i64 * hop_ms;
                FineFeatureFrame {
                    time_ms: presentation_time_ms,
                    presentation_time_ms,
                    values,
                }
            })
            .collect()
    }

    fn v2_distinct_features(ids: &[usize], start_ms: i64, hop_ms: i64) -> Vec<FineFeatureFrame> {
        ids.iter()
            .enumerate()
            .map(|(index, id)| {
                let mut state = (*id as u64).wrapping_add(1).wrapping_mul(0x9e37_79b9);
                let mut values = (0..32)
                    .map(|_| {
                        state = state
                            .wrapping_mul(6_364_136_223_846_793_005)
                            .wrapping_add(1_442_695_040_888_963_407);
                        (((state >> 32) as u32) as f64 / u32::MAX as f64 * 2.0 - 1.0) as f32
                    })
                    .collect::<Vec<_>>();
                let norm = values
                    .iter()
                    .map(|value| f64::from(*value).powi(2))
                    .sum::<f64>()
                    .sqrt();
                for value in &mut values {
                    *value = (f64::from(*value) / norm) as f32;
                }
                let presentation_time_ms = start_ms + index as i64 * hop_ms;
                FineFeatureFrame {
                    time_ms: presentation_time_ms,
                    presentation_time_ms,
                    values,
                }
            })
            .collect()
    }

    fn v2_test_hypothesis(scale: f64, offset_ms: i64) -> AffineHypothesis {
        let training_anchors = (0..24)
            .map(|index| {
                let source_time_ms = index * 100;
                AffineAnchorEvidence {
                    source_time_ms,
                    target_time_ms: (scale * source_time_ms as f64).round() as i64 + offset_ms,
                    residual_ms: 0,
                }
            })
            .collect::<Vec<_>>();
        let held_out_anchors = (0..6)
            .map(|index| {
                let source_time_ms = index * 400 + 50;
                AffineAnchorEvidence {
                    source_time_ms,
                    target_time_ms: (scale * source_time_ms as f64).round() as i64 + offset_ms,
                    residual_ms: 0,
                }
            })
            .collect::<Vec<_>>();
        AffineHypothesis {
            scale,
            offset_ms,
            inlier_count: 24,
            unique_source_count: 24,
            unique_source_coverage: 0.8,
            unique_target_count: 24,
            unique_target_coverage: 0.8,
            source_start_ms: 0,
            source_end_ms: 2_400,
            p50_residual_ms: 15,
            p95_residual_ms: 40,
            max_residual_ms: 60,
            training_anchors,
            held_out_anchors,
            held_out_within_tolerance_count: 6,
        }
    }

    fn v2_test_final_map_hypothesis(scale: f64, stored_residual_ms: i64) -> AffineHypothesis {
        v2_test_final_map_hypothesis_for_duration(scale, stored_residual_ms, 50_000)
    }

    fn v2_test_final_map_hypothesis_for_duration(
        scale: f64,
        stored_residual_ms: i64,
        source_end_ms: i64,
    ) -> AffineHypothesis {
        let create_anchor = |source_time_ms: i64| AffineAnchorEvidence {
            source_time_ms,
            target_time_ms: (scale * source_time_ms as f64).round() as i64,
            residual_ms: stored_residual_ms,
        };
        let at_fraction = |numerator: i64| source_end_ms * numerator / 50;
        let training_anchors = [1, 10, 20, 30, 40, 49]
            .into_iter()
            .map(at_fraction)
            .map(create_anchor)
            .collect::<Vec<_>>();
        let held_out_anchors = [5, 15, 25, 35, 45]
            .into_iter()
            .map(at_fraction)
            .map(create_anchor)
            .collect::<Vec<_>>();
        AffineHypothesis {
            scale,
            offset_ms: 0,
            inlier_count: training_anchors.len(),
            unique_source_count: training_anchors.len(),
            unique_source_coverage: 0.96,
            unique_target_count: training_anchors.len(),
            unique_target_coverage: 0.96,
            source_start_ms: 0,
            source_end_ms,
            p50_residual_ms: stored_residual_ms,
            p95_residual_ms: stored_residual_ms,
            max_residual_ms: stored_residual_ms,
            training_anchors,
            held_out_within_tolerance_count: held_out_anchors.len(),
            held_out_anchors,
        }
    }

