    #[test]
    fn v2_no_eligible_frontier_can_publish_only_a_zero_confidence_blocked_review_time_map() {
        let plan = test_one_source_three_target_batch_plan();
        let receipt = create_test_audio_alignment_batch_fine_frontier_receipt(
            &plan.pairs[0],
            AudioAlignmentBatchFineFrontierStateSnapshot::NoEligibleCandidate,
        );
        let mut proposal = test_audio_alignment_batch_proposal("blocked review candidate");
        let mut time_map = visual_test_time_map(create_v2_span(
            AudioTimeMapSpanKind::Ambiguous,
            0,
            1_000,
            0,
            1_000,
        ));
        time_map.quality.level = "blocked";
        proposal.match_range = Some(AlignmentMatchRange {
            source_start_ms: 0,
            source_end_ms: 1_000,
            target_start_ms: 0,
            target_end_ms: 1_000,
            coverage: 0.9,
        });
        proposal.time_map = Some(time_map);
        let outcome = StagedAudioAlignmentBatchPairOutcome::Proposal(Box::new(proposal.clone()));

        validate_audio_alignment_batch_fine_staged_evidence(&receipt, None, &outcome).unwrap();

        proposal.confidence = 0.1;
        let tampered = StagedAudioAlignmentBatchPairOutcome::Proposal(Box::new(proposal.clone()));
        assert!(
            validate_audio_alignment_batch_fine_staged_evidence(&receipt, None, &tampered).is_err()
        );
        proposal.confidence = 0.0;
        proposal.time_map.as_mut().unwrap().quality.level = "review";
        let tampered = StagedAudioAlignmentBatchPairOutcome::Proposal(Box::new(proposal));
        assert!(
            validate_audio_alignment_batch_fine_staged_evidence(&receipt, None, &tampered).is_err()
        );
    }

    #[test]
    fn v2_resolved_frontier_does_not_publish_an_unselected_conflicting_pair() {
        let plan =
            test_plan_with_selected_global_evidence(test_one_source_three_target_batch_plan());
        let global_selection = &plan.pairs[0].global_selection;
        let reason = "fine frontier 已解析，但当前 pair 因项目级物理时间区间冲突未被选择。";

        let (failed_ranking, failed_selection, failed_outcome) =
            create_v2_unselected_fine_staged_outcome(
                CoreFineFrontierState::Resolved,
                &plan.pairs[0].relation_ranking,
                global_selection,
                reason,
                || panic!("resolved-but-unselected pair must not construct a review proposal"),
            );
        assert_eq!(
            failed_ranking.state,
            AudioAlignmentBatchRelationRankingState::Failed
        );
        validate_audio_alignment_batch_relation_ranking_evidence(&failed_ranking, false).unwrap();
        assert_eq!(
            failed_selection.state,
            AudioAlignmentBatchGlobalSelectionState::Failed
        );
        assert!(!failed_selection.selected);
        assert!(failed_selection
            .top_k
            .iter()
            .all(|candidate| !candidate.global_selected));
        assert!(matches!(
            failed_outcome,
            StagedAudioAlignmentBatchPairOutcome::Failed(error) if error == reason
        ));

        let (review_ranking, review_selection, review_outcome) =
            create_v2_unselected_fine_staged_outcome(
                CoreFineFrontierState::NoEligibleCandidate,
                &plan.pairs[0].relation_ranking,
                global_selection,
                "没有可自动确认的候选。",
                || Box::new(test_audio_alignment_batch_proposal("manual review")),
            );
        assert_eq!(review_ranking.state, plan.pairs[0].relation_ranking.state);
        assert_eq!(
            review_selection.state,
            AudioAlignmentBatchGlobalSelectionState::Selected
        );
        assert!(review_selection.selected);
        assert!(matches!(
            review_outcome,
            StagedAudioAlignmentBatchPairOutcome::Proposal(_)
        ));
    }

    #[test]
    fn v2_no_eligible_frontier_preserves_blocked_review_map_for_global_conflict() {
        let reason =
            "存在全局物理占用冲突，已保留 blocked TimeMap 供人工复核，但不能自动确认或导出。";
        let mut proposal = test_audio_alignment_batch_proposal("blocked review candidate");
        let mut time_map = visual_test_time_map(create_v2_span(
            AudioTimeMapSpanKind::Matched,
            0,
            60_000,
            0,
            60_000,
        ));
        time_map.quality.level = "blocked";
        time_map.quality.coverage = Some(0.91);
        proposal.match_range = Some(AlignmentMatchRange {
            source_start_ms: 0,
            source_end_ms: 60_000,
            target_start_ms: 0,
            target_end_ms: 60_000,
            coverage: 0.91,
        });
        proposal.time_map = Some(time_map);

        let preserved =
            prepare_v2_blocked_review_proposal(Some(Box::new(proposal)), reason).unwrap();
        assert_eq!(preserved.confidence, 0.0);
        assert_eq!(
            preserved
                .time_map
                .as_ref()
                .map(|time_map| time_map.quality.level),
            Some("blocked")
        );
        assert!(preserved.diagnostics.iter().any(|item| item == reason));
        assert!(preserved
            .time_map
            .as_ref()
            .unwrap()
            .quality
            .reasons
            .iter()
            .any(|item| item == reason));
        assert!(preserved
            .time_map
            .as_ref()
            .unwrap()
            .evidence
            .notes
            .iter()
            .any(|item| item == reason));
    }

    #[test]
    fn v2_fine_frontier_inventory_digest_binds_members_and_contiguous_ids() {
        let plan = test_one_source_three_target_batch_plan();
        let mut receipt = create_test_audio_alignment_batch_fine_frontier_receipt(
            &plan.pairs[0],
            AudioAlignmentBatchFineFrontierStateSnapshot::NoEligibleCandidate,
        );
        receipt.inventory_candidates = vec![AudioAlignmentBatchFineInventoryCandidateSnapshot {
            id: AudioAlignmentBatchFineCandidateIdSnapshot {
                pair_ordinal: 1,
                candidate_ordinal: 1,
            },
            coarse_upper_bound_micros: 900_000,
            source_axis_reuse_group_ordinal: None,
            target_axis_reuse_group_ordinal: None,
            members: vec![AudioAlignmentBatchRelationCandidateSnapshot {
                rank: 1,
                source_stream_index: 0,
                target_stream_index: 0,
                score: 0.9,
                global_score: 0.9,
                scale: 1.0,
                offset_ms: 0,
                source_start_ms: 0,
                source_end_ms: 9_000,
                target_start_ms: 0,
                target_end_ms: 9_000,
                inlier_count: 12,
                temporal_coverage: 0.9,
                unique_source_coverage: 0.9,
            }],
        }];
        receipt.inventory_candidate_count = 1;
        receipt.inventory_state_counts.evaluated_ineligible = 1;
        receipt.evaluated_candidate_count = 1;
        receipt.inventory_digest =
            create_v2_fine_inventory_digest(&receipt.inventory_candidates).unwrap();
        receipt = seal_audio_alignment_batch_fine_frontier_receipt(receipt).unwrap();
        validate_audio_alignment_batch_fine_frontier_receipt(&receipt).unwrap();

        let mut changed_window = receipt.clone();
        changed_window.inventory_candidates[0].members[0].source_end_ms += 1;
        changed_window = seal_audio_alignment_batch_fine_frontier_receipt(changed_window).unwrap();
        assert!(validate_audio_alignment_batch_fine_frontier_receipt(&changed_window).is_err());

        let mut ordinal_gap = receipt;
        ordinal_gap.inventory_candidates[0].id.candidate_ordinal = 2;
        ordinal_gap.inventory_digest =
            create_v2_fine_inventory_digest(&ordinal_gap.inventory_candidates).unwrap();
        ordinal_gap = seal_audio_alignment_batch_fine_frontier_receipt(ordinal_gap).unwrap();
        assert!(validate_audio_alignment_batch_fine_frontier_receipt(&ordinal_gap).is_err());
    }

