    #[test]
    fn pair_coarse_groups_same_temporal_window_without_dropping_audio_tracks() {
        let source_window = PresentationRangeMs {
            start_ms: 180_000,
            end_ms: 240_000,
        };
        let target_window = PresentationRangeMs {
            start_ms: 0,
            end_ms: 60_000,
        };
        let mut higher_raw_score =
            v2_test_temporal_window_candidate(4, 8, source_window, target_window, 1.0, 0.95);
        higher_raw_score.hypothesis.unique_source_coverage = 0.05;
        higher_raw_score.intrinsic_margin = 0.01;
        higher_raw_score.repeated_content_only = true;
        let mut higher_global_weight =
            v2_test_temporal_window_candidate(1, 3, source_window, target_window, 1.002, 0.86);
        higher_global_weight.hypothesis.unique_source_coverage = 0.95;
        higher_global_weight.intrinsic_margin = 0.80;

        assert!(v2_pair_coarse_candidates_same_temporal_window(
            &higher_raw_score,
            &higher_global_weight
        ));
        assert!(
            v2_global_candidate_weight(&higher_global_weight)
                > v2_global_candidate_weight(&higher_raw_score)
        );
        let candidates = vec![higher_raw_score, higher_global_weight.clone()];
        let groups = group_v2_pair_coarse_temporal_windows(&candidates);

        assert_eq!(groups.len(), 1);
        assert_eq!(groups[0].member_indices.len(), 2);
        let representative = &candidates[groups[0].member_indices[0]];
        assert_eq!(representative.source_input.stream.stream_index, 1);
        assert_eq!(representative.target_input.stream.stream_index, 3);
        assert_eq!(
            candidates.len(),
            2,
            "grouping must not truncate the executable universe"
        );
        assert_eq!(
            groups[0].member_indices,
            vec![1, 0],
            "fine execution keeps its quality-first member order"
        );

        let plan = test_one_source_three_target_batch_plan();
        let coarse_by_pair = vec![Ok(V2PairCoarseCandidates {
            candidates,
            temporal_window_groups: groups,
            alternatives: Vec::new(),
            diagnostics: Vec::new(),
        })];
        let (_, bindings, _, inventory_evidence, _) =
            create_v2_fine_frontier_inventory(&plan, &coarse_by_pair, &[0]).unwrap();

        assert_eq!(
            bindings[0].member_indices,
            vec![1, 0],
            "canonical evidence must not change fine execution priority"
        );
        assert_eq!(
            inventory_evidence.candidates[0]
                .members
                .iter()
                .map(|member| member.rank)
                .collect::<Vec<_>>(),
            vec![1, 2],
            "inventory evidence must serialize raw ranks in canonical order"
        );
        assert_eq!(
            canonical_v2_fine_member_ranks(&bindings[0].member_indices).unwrap(),
            vec![1, 2],
            "fine execution evidence must publish the same canonical rank set"
        );
        validate_audio_alignment_batch_fine_inventory_candidates(
            &inventory_evidence.candidates,
            &[plan.pairs[0].pair_ordinal],
        )
        .unwrap();
    }

    #[test]
    fn pair_coarse_retains_distinct_windows_on_same_or_different_audio_tracks() {
        let first = v2_test_temporal_window_candidate(
            1,
            2,
            PresentationRangeMs {
                start_ms: 0,
                end_ms: 60_000,
            },
            PresentationRangeMs {
                start_ms: 10_000,
                end_ms: 70_000,
            },
            1.0,
            0.94,
        );
        let same_tracks_different_target = v2_test_temporal_window_candidate(
            1,
            2,
            PresentationRangeMs {
                start_ms: 0,
                end_ms: 60_000,
            },
            PresentationRangeMs {
                start_ms: 120_000,
                end_ms: 180_000,
            },
            1.0,
            0.90,
        );
        let different_tracks_different_source = v2_test_temporal_window_candidate(
            4,
            8,
            PresentationRangeMs {
                start_ms: 240_000,
                end_ms: 300_000,
            },
            PresentationRangeMs {
                start_ms: 10_000,
                end_ms: 70_000,
            },
            1.0,
            0.86,
        );

        assert!(!v2_pair_coarse_candidates_same_temporal_window(
            &first,
            &same_tracks_different_target,
        ));
        assert!(!v2_pair_coarse_candidates_same_temporal_window(
            &first,
            &different_tracks_different_source,
        ));
        let candidates = [
            different_tracks_different_source,
            first,
            same_tracks_different_target,
        ];
        let groups = group_v2_pair_coarse_temporal_windows(&candidates);

        assert_eq!(groups.len(), 3);
        assert!(groups.iter().all(|group| group.member_indices.len() == 1));
    }

    #[test]
    fn pair_coarse_temporal_window_grouping_is_order_independent() {
        let source_window = PresentationRangeMs {
            start_ms: 30_000,
            end_ms: 90_000,
        };
        let target_window = PresentationRangeMs {
            start_ms: 0,
            end_ms: 60_000,
        };
        let canonical =
            v2_test_temporal_window_candidate(1, 2, source_window, target_window, 1.0, 0.90);
        let duplicate =
            v2_test_temporal_window_candidate(5, 6, source_window, target_window, 1.0, 0.90);
        let distinct = v2_test_temporal_window_candidate(
            3,
            4,
            PresentationRangeMs {
                start_ms: 150_000,
                end_ms: 210_000,
            },
            target_window,
            1.0,
            0.85,
        );
        let forward_candidates = [duplicate.clone(), distinct.clone(), canonical.clone()];
        let reverse_candidates = [canonical, distinct, duplicate];
        let forward = group_v2_pair_coarse_temporal_windows(&forward_candidates);
        let reverse = group_v2_pair_coarse_temporal_windows(&reverse_candidates);
        let signature = |candidate: &V2TrackPairCandidate| {
            (
                candidate.source_input.stream.stream_index,
                candidate.target_input.stream.stream_index,
                candidate.global_source_interval,
                candidate.global_target_interval,
                candidate.score.to_bits(),
            )
        };
        let group_signatures =
            |groups: &[V2TemporalWindowGroup], candidates: &[V2TrackPairCandidate]| {
                groups
                    .iter()
                    .map(|group| {
                        group
                            .member_indices
                            .iter()
                            .map(|index| signature(&candidates[*index]))
                            .collect::<Vec<_>>()
                    })
                    .collect::<Vec<_>>()
            };

        assert_eq!(
            group_signatures(&forward, &forward_candidates),
            group_signatures(&reverse, &reverse_candidates)
        );
        assert_eq!(forward.len(), 2);
        assert_eq!(
            forward
                .iter()
                .map(|group| group.member_indices.len())
                .sum::<usize>(),
            3
        );
    }

