    #[test]
    fn v2_cache_key_reuses_same_actual_backend_across_requested_policy() {
        let path = temp_audio_cache_path("v2-cache-policy");
        std::fs::write(&path, b"media-policy").unwrap();
        let path_text = path.to_string_lossy().to_string();
        let mut cpu_options = test_options();
        cpu_options.spectral_backend_request =
            resolve_spectral_backend_preference(SpectralBackendPreference::Cpu).unwrap();
        let mut auto_options = test_options();
        auto_options.spectral_backend_request =
            resolve_spectral_backend_preference(SpectralBackendPreference::Auto).unwrap();
        let input = test_audio_input(1, 80);

        let cpu_key = create_v2_audio_cache_key_for_backend(
            &path_text,
            &cpu_options,
            &input,
            "landmark",
            CPU_SPECTRAL_BACKEND_ID,
        )
        .unwrap();
        let auto_cpu_key = create_v2_audio_cache_key_for_backend(
            &path_text,
            &auto_options,
            &input,
            "landmark",
            CPU_SPECTRAL_BACKEND_ID,
        )
        .unwrap();
        let legacy_cpu_key = create_v2_legacy_policy_bound_cache_key_for_backend(
            &path_text,
            &cpu_options,
            &input,
            "landmark",
            CPU_SPECTRAL_BACKEND_ID,
            "cpu",
        )
        .unwrap();
        let legacy_auto_key = create_v2_legacy_policy_bound_cache_key_for_backend(
            &path_text,
            &auto_options,
            &input,
            "landmark",
            CPU_SPECTRAL_BACKEND_ID,
            "auto",
        )
        .unwrap();

        assert!(!cpu_key.contains("requestedSpectralBackend="));
        assert!(!auto_cpu_key.contains("requestedSpectralBackend="));
        assert!(cpu_key.contains(CPU_SPECTRAL_BACKEND_ID));
        assert!(auto_cpu_key.contains(CPU_SPECTRAL_BACKEND_ID));
        assert_eq!(cpu_key, auto_cpu_key);
        assert!(legacy_cpu_key.contains("requestedSpectralBackend=cpu"));
        assert!(legacy_auto_key.contains("requestedSpectralBackend=auto"));
        assert!(legacy_cpu_key.contains("alignment-v2.3-rust"));
        assert!(legacy_cpu_key
            .contains("pcm-s16le-16k-pts-streaming-cuda-affine-window-version-reuse-frontier-v23"));
        assert_ne!(legacy_cpu_key, legacy_auto_key);
        assert_ne!(cpu_key, legacy_cpu_key);
        std::fs::remove_file(path).unwrap();
    }

