    #[test]
    fn v2_codec_perturbed_shared_content_survives_before_unrelated_source_tail() {
        let shared_ids = (0..540usize).collect::<Vec<_>>();
        let mut source_ids = shared_ids.clone();
        source_ids.extend(10_000..10_090);
        let source = v2_distinct_features(&source_ids, 0, 1_000);
        let mut target = v2_distinct_features(&shared_ids, 0, 1_000);

        // Apply one norm-preserving rotation to every feature vector. Corresponding frames keep
        // cosine similarity 0.92 (cost 80), modelling systematic codec/feature drift without
        // making unrelated frame identities any less distinct.
        let cosine = 0.92_f64;
        let sine = (1.0 - cosine * cosine).sqrt();
        for frame in &mut target {
            for pair in frame.values.chunks_exact_mut(2) {
                let left = f64::from(pair[0]);
                let right = f64::from(pair[1]);
                pair[0] = (cosine * left - sine * right) as f32;
                pair[1] = (sine * left + cosine * right) as f32;
            }
        }

        let coarse = v2_test_hypothesis(1.0, 0);
        let result =
            align_v2_feature_chunks(&source, &target, &coarse, &test_options(), 0, None).unwrap();
        let matched_ms = result
            .spans
            .iter()
            .filter(|span| span.kind == AudioTimeMapSpanKind::Matched)
            .map(|span| span.target_end_ms.saturating_sub(span.target_start_ms))
            .sum::<u64>();
        let trailing_source_ms = result
            .spans
            .iter()
            .filter(|span| span.source_end_ms > 540_000)
            .map(|span| {
                span.source_end_ms
                    .saturating_sub(span.source_start_ms.max(540_000))
            })
            .sum::<u64>();

        assert!(
            matched_ms >= 500_000,
            "codec drift must not erase the shared program: matched={matched_ms}, spans={:?}",
            result.spans
        );
        assert!(
            trailing_source_ms >= 70_000,
            "the unrelated source tail must remain reviewable: trailing={trailing_source_ms}, spans={:?}",
            result.spans
        );
        validate_v2_time_map_spans(&result.spans).unwrap();
    }

