    #[test]
    fn fine_window_ffmpeg_args_use_input_seek_and_bounded_output_duration() {
        let input = test_audio_input(4, 0);
        let args = pcm_decode::window_audio_args(
            "private-long-reference.mkv",
            input.stream.stream_index,
            ALIGNMENT_V2_SAMPLE_RATE,
            input.decode_timeline.as_ref(),
            3_723_456,
            1_234_567,
        )
        .unwrap();
        let seek_index = args.iter().position(|arg| arg == "-ss").unwrap();
        let input_index = args.iter().position(|arg| arg == "-i").unwrap();
        let duration_index = args.iter().position(|arg| arg == "-t").unwrap();
        assert!(seek_index < input_index, "-ss must be an input option");
        assert!(duration_index > input_index, "-t must bound decoded output");
        assert_eq!(args[seek_index + 1], "3723.456");
        assert_eq!(args[duration_index + 1], "1234.567");
        assert!(!args.iter().any(|arg| arg == "-copyts"));
        assert_eq!(args.last().map(String::as_str), Some("pipe:1"));
    }

    #[test]
    fn continuous_pts_decode_args_use_sample_clock_without_async_compensation() {
        let input = test_audio_input(4, 0);
        let coarse = pcm_decode::complete_audio_args(
            "continuous.dts",
            input.stream.stream_index,
            ALIGNMENT_V2_SAMPLE_RATE,
            input.decode_timeline.as_ref(),
        )
        .unwrap();
        let complete = pcm_decode::complete_audio_args(
            "continuous.dts",
            input.stream.stream_index,
            ALIGNMENT_V2_SAMPLE_RATE,
            input.decode_timeline.as_ref(),
        )
        .unwrap();
        let window = pcm_decode::window_audio_args(
            "continuous.dts",
            input.stream.stream_index,
            ALIGNMENT_V2_SAMPLE_RATE,
            input.decode_timeline.as_ref(),
            3_723_456,
            1_234_567,
        )
        .unwrap();

        for args in [&coarse, &complete, &window] {
            let filter_index = args.iter().position(|arg| arg == "-af").unwrap();
            assert_eq!(
                args[filter_index + 1],
                format!("aresample={ALIGNMENT_V2_SAMPLE_RATE},asetpts=N/SR/TB")
            );
            assert!(!args.iter().any(|arg| arg.contains("async=")));
        }
        assert!(coarse.iter().any(|arg| arg == "-copyts"));
        assert!(complete.iter().any(|arg| arg == "-copyts"));
        assert!(!window.iter().any(|arg| arg == "-copyts"));
    }

