    #[test]
    fn windowed_boundary_refinement_uses_absolute_pcm_offsets() {
        let mut state = 0x1234_5678_u64;
        let pcm = (0..ALIGNMENT_V2_SAMPLE_RATE as usize * 2)
            .map(|_| {
                state = state
                    .wrapping_mul(6_364_136_223_846_793_005)
                    .wrapping_add(1_442_695_040_888_963_407);
                (state >> 48) as i16
            })
            .collect::<Vec<_>>();
        let mut spans = vec![
            create_v2_span(
                AudioTimeMapSpanKind::Matched,
                100_000,
                101_000,
                200_000,
                201_000,
            ),
            create_v2_span(
                AudioTimeMapSpanKind::Matched,
                101_000,
                102_000,
                201_000,
                202_000,
            ),
        ];

        let summary = refine_v2_span_boundaries(&mut spans, &pcm, &pcm, 100_000, 200_000, None);

        assert_eq!(summary.attempted_count, 1);
        assert_eq!(summary.refined_count, 1);
        assert_eq!(spans[0].source_end_ms, 101_000);
        assert_eq!(spans[0].target_end_ms, 201_000);
    }

    #[test]
    fn v2_silent_source_only_boundaries_are_attempted_but_remain_blocking() {
        let mut spans = vec![
            create_v2_span(AudioTimeMapSpanKind::Matched, 0, 10_000, 0, 10_000),
            create_v2_span(
                AudioTimeMapSpanKind::SourceOnly,
                10_000,
                20_000,
                10_000,
                10_000,
            ),
            create_v2_span(
                AudioTimeMapSpanKind::Matched,
                20_000,
                30_000,
                10_000,
                20_000,
            ),
        ];
        let pcm = vec![0i16; ALIGNMENT_V2_SAMPLE_RATE as usize * 31];
        let summary = refine_v2_span_boundaries(&mut spans, &pcm, &pcm, 0, 0, None);

        assert_eq!(summary.attempted_count, 2);
        assert_eq!(summary.refined_count, 0);
        assert_eq!(summary.ambiguous_count, 2);
        assert!(summary.max_uncertainty_ms.is_some_and(|value| value >= 150));
        assert!(summary
            .evidence_notes
            .iter()
            .any(|note| note.contains("不会把粗 DP 边界冒充精确时间")));
        assert_eq!(spans[1].boundaries.start.support_duration_ms, 10_000);
        assert_eq!(spans[1].boundaries.end.support_duration_ms, 10_000);
        assert_eq!(
            spans[1].boundaries.start.status,
            AudioTimeMapBoundaryStatus::Ambiguous
        );
    }

