    #[test]
    #[ignore = "requires user-provided source/target media and can run for several minutes"]
    fn production_real_media_approximate_fingerprint_profile_from_environment() {
        let source_path = std::env::var("C137_REAL_MEDIA_SOURCE")
            .expect("C137_REAL_MEDIA_SOURCE must point to one reference video");
        let target_path = std::env::var("C137_REAL_MEDIA_TARGETS")
            .expect("C137_REAL_MEDIA_TARGETS must contain one target video path")
            .split('|')
            .map(str::trim)
            .find(|path| !path.is_empty())
            .expect("C137_REAL_MEDIA_TARGETS must contain one target video path")
            .to_string();
        assert!(Path::new(&source_path).is_file());
        assert!(Path::new(&target_path).is_file());
        let backend_request = resolve_spectral_backend_preference(SpectralBackendPreference::Cuda)
            .expect("CUDA backend must be available for the real-media profile");
        let options = AudioAlignmentOptions {
            spectral_backend_request: backend_request.clone(),
            ..test_options()
        };
        let source_identity =
            probe_media_content_identity_cancellable(Path::new(&source_path), None)
                .expect("source full-file identity must complete");
        let target_identity =
            probe_media_content_identity_cancellable(Path::new(&target_path), None)
                .expect("target full-file identity must complete");
        let create_input = |identity, duration_ms| AlignmentAudioInput {
            presentation_origin_ms: 0,
            media_duration_ms: Some(duration_ms),
            content_identity: Some(identity),
            decode_timeline: None,
            audio_stream_count: 1,
            explicit_stream_selection: true,
            stream: AudioStreamProbe {
                stream_index: 1,
                codec_name: None,
                start_time_ms: 0,
                timeline_offset_ms: 0,
                duration_ms: None,
                time_base: None,
                sample_rate: None,
                channels: None,
                channel_layout: None,
                language: None,
                title: None,
                is_default: true,
                is_commentary: false,
            },
        };
        let source_input = create_input(source_identity.clone(), 8 * 60 * 60 * 1_000);
        let target_input = create_input(target_identity.clone(), 4 * 60 * 60 * 1_000);
        let source_guard = PinnedMediaIdentityGuard {
            physical_pin: PinnedPhysicalFile::open(Path::new(&source_path)).unwrap(),
            expected_identity: source_identity,
        };
        let target_guard = PinnedMediaIdentityGuard {
            physical_pin: PinnedPhysicalFile::open(Path::new(&target_path)).unwrap(),
            expected_identity: target_identity,
        };
        let stable_source_path = source_guard
            .physical_pin
            .handle_final_path()
            .to_string_lossy()
            .into_owned();
        let stable_target_path = target_guard
            .physical_pin
            .handle_final_path()
            .to_string_lossy()
            .into_owned();
        let started_at = Instant::now();
        let source = decode_v2_coarse_landmarks_streaming(
            &stable_source_path,
            "真实参考",
            &options,
            &source_input,
            &backend_request,
            None,
            Some(&source_guard),
        )
        .expect("source streaming landmarks must decode");
        let target = decode_v2_coarse_landmarks_streaming(
            &stable_target_path,
            "真实目标",
            &options,
            &target_input,
            &backend_request,
            None,
            Some(&target_guard),
        )
        .expect("target streaming landmarks must decode");
        let source_bounds =
            v2_presentation_bounds_for_samples(0, source.decoded_sample_count).unwrap();
        let target_bounds =
            v2_presentation_bounds_for_samples(0, target.decoded_sample_count).unwrap();
        let result = match_spectral_fingerprints_approximately(
            &source.coarse_fingerprint,
            &target.coarse_fingerprint,
            (source_bounds.start_ms, source_bounds.end_ms),
            (target_bounds.start_ms, target_bounds.end_ms),
            &ApproximateFingerprintConfig::default(),
            None,
        )
        .expect("approximate fingerprint profile must execute");
        eprintln!(
            "C137 approximate fingerprint profile: elapsedMs={} sourceLandmarks={} targetLandmarks={} sourceFingerprintFrames={} targetFingerprintFrames={} sourceBounds={source_bounds:?} targetBounds={target_bounds:?} result={result:#?}",
            started_at.elapsed().as_millis(),
            source.index.landmarks.len(),
            target.index.landmarks.len(),
            source.coarse_fingerprint.len(),
            target.coarse_fingerprint.len()
        );
    }

    #[test]
    #[ignore = "requires user-provided real media and can run for several minutes"]
    fn production_real_media_batch_smoke_from_environment() {
        let source_paths = std::env::var("C137_REAL_MEDIA_SOURCES")
            .ok()
            .or_else(|| std::env::var("C137_REAL_MEDIA_SOURCE").ok())
            .expect("C137_REAL_MEDIA_SOURCE(S) must contain one or more reference video paths")
            .split('|')
            .map(str::trim)
            .filter(|path| !path.is_empty())
            .map(str::to_string)
            .collect::<Vec<_>>();
        let target_paths = std::env::var("C137_REAL_MEDIA_TARGETS")
            .expect("C137_REAL_MEDIA_TARGETS must contain | separated target video paths")
            .split('|')
            .map(str::trim)
            .filter(|path| !path.is_empty())
            .map(str::to_string)
            .collect::<Vec<_>>();
        assert!(
            !source_paths.is_empty(),
            "C137_REAL_MEDIA_SOURCE(S) must contain at least one path"
        );
        for source_path in &source_paths {
            assert!(
                Path::new(source_path).is_file(),
                "C137_REAL_MEDIA_SOURCE(S) contains a non-file path"
            );
        }
        assert!(
            !target_paths.is_empty(),
            "C137_REAL_MEDIA_TARGETS must contain at least one path"
        );
        for target_path in &target_paths {
            assert!(
                Path::new(target_path).is_file(),
                "C137_REAL_MEDIA_TARGETS contains a non-file path"
            );
        }
        let spectral_backend = match std::env::var("C137_REAL_MEDIA_BACKEND")
            .unwrap_or_else(|_| "cuda".to_string())
            .trim()
            .to_ascii_lowercase()
            .as_str()
        {
            "auto" => SpectralBackendPreference::Auto,
            "cpu" => SpectralBackendPreference::Cpu,
            "cuda" => SpectralBackendPreference::Cuda,
            value => panic!("C137_REAL_MEDIA_BACKEND must be auto, cpu, or cuda; got {value:?}"),
        };
        let requested_backend = match spectral_backend {
            SpectralBackendPreference::Auto => "auto",
            SpectralBackendPreference::Cpu => "cpu",
            SpectralBackendPreference::Cuda => "cuda",
        };
        let source_audio_stream_index = std::env::var("C137_REAL_MEDIA_SOURCE_AUDIO_STREAM")
            .ok()
            .map(|value| {
                value
                    .trim()
                    .parse::<u32>()
                    .expect("C137_REAL_MEDIA_SOURCE_AUDIO_STREAM must be an unsigned integer")
            });
        let target_audio_stream_index = std::env::var("C137_REAL_MEDIA_TARGET_AUDIO_STREAM")
            .ok()
            .map(|value| {
                value
                    .trim()
                    .parse::<u32>()
                    .expect("C137_REAL_MEDIA_TARGET_AUDIO_STREAM must be an unsigned integer")
            });
        let sources = source_paths
            .iter()
            .enumerate()
            .map(|(index, path)| AudioAlignmentBatchMediaRequest {
                media_id: format!("real-reference-{:03}", index + 1),
                path: path.clone(),
                audio_stream_index: source_audio_stream_index,
                video_stream_index: None,
            })
            .collect::<Vec<_>>();
        let targets = target_paths
            .iter()
            .enumerate()
            .map(|(index, path)| AudioAlignmentBatchMediaRequest {
                media_id: format!("real-target-{:03}", index + 1),
                path: path.clone(),
                audio_stream_index: target_audio_stream_index,
                video_stream_index: None,
            })
            .collect::<Vec<_>>();
        let pairs = if sources.len() > 1 && targets.len() == 1 {
            Some(
                sources
                    .iter()
                    .map(|source| AudioAlignmentBatchPairRequest {
                        source_media_id: source.media_id.clone(),
                        target_media_id: targets[0].media_id.clone(),
                    })
                    .collect(),
            )
        } else {
            None
        };
        let request = AudioAlignmentBatchRequest {
            schema_version: AUDIO_ALIGNMENT_BATCH_SCHEMA_VERSION,
            sources,
            targets,
            pairs,
            version_reuse_groups: Vec::new(),
            ffmpeg_path: Some("ffmpeg".to_string()),
            ffprobe_path: Some("ffprobe".to_string()),
            spectral_backend: Some(spectral_backend),
            sample_rate: None,
            window_ms: Some(1_000),
            match_threshold: Some(0.35),
            min_gap_ms: Some(3_000),
            max_cells: None,
            enable_visual_evidence: Some(false),
            visual_sample_interval_ms: None,
            localization_mode: Some(true),
        };

        let plan =
            plan_audio_alignment_batch(request).expect("real-media batch plan must validate");
        let job_id = format!("real-media-smoke-{}", current_time_ms());
        let cancel_flag = Arc::new(AtomicBool::new(false));
        insert_audio_alignment_batch_job(&job_id, &plan, cancel_flag.clone())
            .expect("real-media batch job must enter the native queue");
        let worker_job_id = job_id.clone();
        let started_at = std::time::Instant::now();
        let worker = std::thread::spawn(move || {
            run_audio_alignment_batch_job(worker_job_id, cancel_flag, plan);
        });
        let terminal = loop {
            let snapshot =
                get_audio_alignment_batch_job(job_id.clone()).expect("real-media job must exist");
            eprintln!(
                "C137 real-media smoke: elapsed={}s status={:?} progress={:.3} processed={}/{} failed={} current={:?} message={}",
                started_at.elapsed().as_secs(),
                snapshot.status,
                snapshot.progress,
                snapshot.processed_pair_count,
                snapshot.total_pair_count,
                snapshot.failed_pair_count,
                snapshot.current_pair_ordinal,
                snapshot.message
            );
            if matches!(
                snapshot.status,
                AudioAlignmentJobStatus::Completed
                    | AudioAlignmentJobStatus::Failed
                    | AudioAlignmentJobStatus::Cancelled
            ) {
                break snapshot;
            }
            std::thread::sleep(std::time::Duration::from_secs(5));
        };
        worker
            .join()
            .expect("real-media batch worker must not panic");

        let elapsed_ms = u64::try_from(started_at.elapsed().as_millis()).unwrap_or(u64::MAX);
        let receipt = serde_json::json!({
            "schemaVersion": 1,
            "evidenceKind": "c137-development-real-media-smoke",
            "releaseEligible": false,
            "requestedBackend": requested_backend,
            "elapsedMs": elapsed_ms,
            "snapshot": terminal
        });
        if let Ok(output_path) = std::env::var("C137_REAL_MEDIA_OUTPUT") {
            let output_path = PathBuf::from(output_path);
            if let Some(parent) = output_path.parent() {
                std::fs::create_dir_all(parent)
                    .expect("real-media smoke output directory must be writable");
            }
            std::fs::write(
                output_path,
                format!(
                    "{}\n",
                    serde_json::to_string_pretty(&receipt)
                        .expect("real-media smoke receipt must serialize")
                ),
            )
            .expect("real-media smoke receipt must be writable");
        }
        eprintln!(
            "C137 real-media terminal: elapsed={elapsed_ms}ms status={:?} processed={}/{} failed={}",
            terminal.status,
            terminal.processed_pair_count,
            terminal.total_pair_count,
            terminal.failed_pair_count
        );
        for pair in &terminal.pairs {
            if let Some(error) = pair.error.as_deref() {
                eprintln!(
                    "C137 real-media pair {} failed: {}",
                    pair.pair_ordinal, error
                );
            }
        }
        assert_eq!(
            terminal.status,
            AudioAlignmentJobStatus::Completed,
            "real-media batch failed: {:?}",
            terminal.error
        );
        assert_eq!(
            terminal.failed_pair_count, 0,
            "real-media batch contains failed pairs"
        );
    }

    #[test]
    fn ffmpeg_v2_vfr_container_keeps_audio_pts_and_bilateral_edit_boundaries() {
        if !ffmpeg_test_tools_available() {
            eprintln!("跳过 Alignment V2 VFR 金标准：ffmpeg/ffprobe 不可用。");
            return;
        }
        let directory = std::env::temp_dir().join(format!(
            "alignment-v2-vfr-{}-{}",
            std::process::id(),
            current_time_ms()
        ));
        std::fs::create_dir_all(&directory).unwrap();
        let source_path = directory.join("source-vfr-negative-pts.mkv");
        let target_path = directory.join("target-vfr-positive-pts.mkv");
        generate_v2_vfr_ffmpeg_fixture(
            &source_path,
            "[0:a]asplit=2[x0][x1];[x0]atrim=start=0:end=5,asetpts=PTS-STARTPTS[a0];[x1]atrim=start=6:end=16,asetpts=PTS-STARTPTS[a1];[a0][a1]concat=n=2:v=0:a=1[main]",
            "select=not(mod(n\\,2))+not(mod(n\\,5))",
            "-0.25",
        );
        generate_v2_vfr_ffmpeg_fixture(
            &target_path,
            "[0:a]asplit=2[x0][x1];[x0]atrim=start=0:end=11,asetpts=PTS-STARTPTS[a0];[x1]atrim=start=12:end=16,asetpts=PTS-STARTPTS[a1];[a0][a1]concat=n=2:v=0:a=1,atempo=0.980392[main]",
            "select=not(mod(n\\,3))+not(mod(n\\,7))",
            "0.5",
        );

        assert_genuine_vfr_pts(&source_path, -250);
        assert_genuine_vfr_pts(&target_path, 500);
        let source_snapshot =
            probe_media_timeline_with_ffprobe(&source_path.to_string_lossy(), Path::new("ffprobe"))
                .unwrap();
        let target_snapshot =
            probe_media_timeline_with_ffprobe(&target_path.to_string_lossy(), Path::new("ffprobe"))
                .unwrap();
        let source_audio = source_snapshot.audio_streams.first().unwrap();
        let target_audio = target_snapshot.audio_streams.first().unwrap();
        assert_eq!(source_audio.start_time_ms, -250);
        assert_eq!(target_audio.start_time_ms, 500);
        assert_eq!(source_audio.timeline_offset_ms, 0);
        assert_eq!(target_audio.timeline_offset_ms, 0);
        let source_decode_timeline = probe_audio_decode_timelines_with_ffprobe(
            &source_path.to_string_lossy(),
            Path::new("ffprobe"),
        )
        .unwrap();
        let target_decode_timeline = probe_audio_decode_timelines_with_ffprobe(
            &target_path.to_string_lossy(),
            Path::new("ffprobe"),
        )
        .unwrap();
        assert_eq!(
            source_decode_timeline
                .get(&source_audio.stream_index)
                .and_then(|timeline| timeline.first_decoded_pts_ms),
            Some(-250)
        );
        assert_eq!(
            target_decode_timeline
                .get(&target_audio.stream_index)
                .and_then(|timeline| timeline.first_decoded_pts_ms),
            Some(500)
        );

        let proposal = align_audio_files_inner(AudioAlignmentRequest {
            algorithm: None,
            complete_path: target_path.to_string_lossy().to_string(),
            source_path: source_path.to_string_lossy().to_string(),
            ffmpeg_path: Some("ffmpeg".to_string()),
            ffprobe_path: Some("ffprobe".to_string()),
            complete_audio_stream_index: None,
            source_audio_stream_index: None,
            complete_video_stream_index: None,
            source_video_stream_index: None,
            spectral_backend: Some(SpectralBackendPreference::Cpu),
            sample_rate: None,
            window_ms: None,
            match_threshold: None,
            min_gap_ms: None,
            max_cells: Some(ALIGNMENT_V2_MAX_DP_CELLS),
            enable_visual_evidence: Some(false),
            visual_sample_interval_ms: None,
            localization_mode: Some(true),
        })
        .unwrap();
        let time_map = proposal
            .time_map
            .as_ref()
            .expect("VFR 容器应输出音频时间图");

        assert_eq!(
            time_map.source_stream.as_ref().unwrap().stream_type,
            "audio"
        );
        assert_eq!(
            time_map.target_stream.as_ref().unwrap().stream_type,
            "audio"
        );
        assert_eq!(
            time_map.source_stream.as_ref().unwrap().start_ms,
            Some(-250)
        );
        assert_eq!(time_map.target_stream.as_ref().unwrap().start_ms, Some(500));
        assert_eq!(
            time_map.source_stream.as_ref().unwrap().timeline_offset_ms,
            Some(0)
        );
        assert_eq!(
            time_map.target_stream.as_ref().unwrap().timeline_offset_ms,
            Some(0)
        );
        assert_eq!(time_map.evidence.types, vec!["audio"]);
        assert_v2_bilateral_edit_gold(time_map);
        assert!((time_map.evidence.alternative_track_scores[0].scale - 1.02).abs() < 0.01);
        let _ = std::fs::remove_dir_all(directory);
    }

    #[test]
    fn ffmpeg_v2_visual_fallback_localizes_video_without_audio() {
        if !ffmpeg_test_tools_available() {
            eprintln!("跳过 Alignment V2 视觉回退集成测试：ffmpeg/ffprobe 不可用。");
            return;
        }
        let directory = std::env::temp_dir().join(format!(
            "alignment-v2-visual-{}-{}",
            std::process::id(),
            current_time_ms()
        ));
        std::fs::create_dir_all(&directory).unwrap();
        let source_path = directory.join("source-video-only.mkv");
        let target_path = directory.join("target-video-only.mkv");
        let source_status = Command::new("ffmpeg")
            .args([
                "-y",
                "-v",
                "error",
                "-f",
                "lavfi",
                "-i",
                "testsrc2=size=160x90:rate=10:duration=12",
                "-an",
                "-c:v",
                "ffv1",
            ])
            .arg(&source_path)
            .status()
            .unwrap();
        assert!(source_status.success());
        let target_status = Command::new("ffmpeg")
            .args([
                "-y",
                "-v",
                "error",
                "-f",
                "lavfi",
                "-i",
                "color=black:size=160x90:rate=10:duration=8",
                "-f",
                "lavfi",
                "-i",
                "testsrc2=size=160x90:rate=10:duration=12",
                "-filter_complex",
                "[0:v][1:v]concat=n=2:v=1:a=0[v]",
                "-map",
                "[v]",
                "-an",
                "-c:v",
                "ffv1",
            ])
            .arg(&target_path)
            .status()
            .unwrap();
        assert!(target_status.success());

        let proposal = align_audio_files_inner(AudioAlignmentRequest {
            algorithm: None,
            complete_path: target_path.to_string_lossy().to_string(),
            source_path: source_path.to_string_lossy().to_string(),
            ffmpeg_path: Some("ffmpeg".to_string()),
            ffprobe_path: Some("ffprobe".to_string()),
            complete_audio_stream_index: None,
            source_audio_stream_index: None,
            complete_video_stream_index: None,
            source_video_stream_index: None,
            spectral_backend: Some(SpectralBackendPreference::Cpu),
            sample_rate: None,
            window_ms: None,
            match_threshold: None,
            min_gap_ms: None,
            max_cells: Some(ALIGNMENT_V2_MAX_DP_CELLS),
            enable_visual_evidence: Some(false),
            visual_sample_interval_ms: Some(1_000),
            localization_mode: Some(true),
        })
        .unwrap();
        let time_map = proposal.time_map.as_ref().unwrap_or_else(|| {
            panic!(
                "视觉回退应输出 timeMap；diagnostics={:?}",
                proposal.diagnostics
            )
        });
        assert_eq!(time_map.quality.level, "review");
        assert_eq!(
            time_map.feature_version,
            ALIGNMENT_V2_VISUAL_FEATURE_VERSION
        );
        assert_eq!(time_map.spans[0].kind, AudioTimeMapSpanKind::Matched);
        assert_eq!(
            time_map.source_stream.as_ref().unwrap().stream_type,
            "video"
        );
        assert_eq!(
            time_map.target_stream.as_ref().unwrap().stream_type,
            "video"
        );
        assert_eq!(
            time_map.source_visual_stream.as_ref().unwrap().index,
            time_map.source_stream.as_ref().unwrap().index
        );
        assert_eq!(
            time_map.target_visual_stream.as_ref().unwrap().index,
            time_map.target_stream.as_ref().unwrap().index
        );
        assert!(time_map.target_start_ms.abs_diff(8_000) <= 1_000);
        assert!(time_map.evidence.types.contains(&"visual"));
        assert!(!time_map.evidence.types.contains(&"audio"));
        let _ = std::fs::remove_dir_all(directory);
    }

    #[test]
    fn ffmpeg_v2_pts_gap_is_preserved_as_silence_instead_of_being_flattened() {
        if !ffmpeg_test_tools_available() {
            eprintln!("跳过 Alignment V2 PTS gap 测试：ffmpeg/ffprobe 不可用。");
            return;
        }
        let directory = std::env::temp_dir().join(format!(
            "alignment-v2-pts-gap-{}-{}",
            std::process::id(),
            current_time_ms()
        ));
        std::fs::create_dir_all(&directory).unwrap();
        let media_path = directory.join("five-second-middle-gap.mka");
        let status = Command::new("ffmpeg")
            .args([
                "-y",
                "-v",
                "error",
                "-f",
                "lavfi",
                "-i",
                "aevalsrc=if(lt(t\\,4)\\,0.6*sin(2*PI*440*t)\\,0.6*sin(2*PI*880*t)):s=16000:d=8",
                "-af",
                "asetpts=PTS+5/TB*gte(T\\,4)",
                "-c:a",
                "pcm_s16le",
            ])
            .arg(&media_path)
            .status()
            .unwrap();
        assert!(status.success(), "PTS gap fixture 生成失败");

        let snapshot =
            probe_media_timeline_with_ffprobe(&media_path.to_string_lossy(), Path::new("ffprobe"))
                .unwrap();
        let timelines = probe_audio_decode_timelines_with_ffprobe(
            &media_path.to_string_lossy(),
            Path::new("ffprobe"),
        )
        .unwrap();
        let stream = snapshot.audio_streams[0].clone();
        let evidence = timelines.get(&stream.stream_index).cloned().unwrap();
        assert_eq!(evidence.pts_discontinuity_count, 1);
        assert!(evidence.max_pts_gap_ms.is_some_and(|gap| gap >= 4_900));
        let input = alignment_audio_input_from_snapshot(&snapshot, stream, true, Some(evidence));
        let pcm = decode_v2_pcm(
            &media_path.to_string_lossy(),
            "PTS gap fixture",
            &test_options(),
            &input,
            None,
            None,
        )
        .unwrap();
        let sample_rate = ALIGNMENT_V2_SAMPLE_RATE as usize;
        let middle_gap = &pcm[5 * sample_rate..8 * sample_rate];
        let post_gap = &pcm[10 * sample_rate..11 * sample_rate];
        let mean_abs = |samples: &[i16]| {
            samples
                .iter()
                .map(|sample| i64::from(*sample).abs() as f64)
                .sum::<f64>()
                / samples.len() as f64
        };

        assert!(pcm.len() >= 12 * sample_rate, "samples={}", pcm.len());
        assert!(
            mean_abs(middle_gap) < 10.0,
            "gap energy={}",
            mean_abs(middle_gap)
        );
        assert!(
            mean_abs(post_gap) > 1_000.0,
            "post energy={}",
            mean_abs(post_gap)
        );
        let _ = std::fs::remove_dir_all(directory);
    }

