    #[test]
    fn batch_shared_preparation_is_observable_before_any_pair_starts() {
        let job_id = "test-batch-shared-preparation".to_string();
        let plan = plan_audio_alignment_batch(test_audio_alignment_batch_request(None)).unwrap();
        let cancel_flag = Arc::new(AtomicBool::new(false));
        insert_audio_alignment_batch_job(&job_id, &plan, cancel_flag).unwrap();

        update_audio_alignment_batch_phase(
            &job_id,
            0.08,
            "正在预处理第 1/4 个素材：读取 PTS、音轨并生成共享声谱特征。",
        )
        .unwrap();

        let preparing = get_audio_alignment_batch_job(job_id.clone()).unwrap();
        assert_eq!(preparing.status, AudioAlignmentJobStatus::Running);
        assert_eq!(preparing.current_pair_ordinal, None);
        assert_eq!(preparing.progress, 0.08);
        assert!(preparing.message.contains("正在预处理第 1/4 个素材"));
        assert!(preparing
            .pairs
            .iter()
            .all(|pair| pair.status == AudioAlignmentJobStatus::Queued));
        assert!(preparing
            .pairs
            .iter()
            .all(|pair| pair.message.contains("正在预处理第 1/4 个素材")));

        update_audio_alignment_batch_pair_progress(
            &job_id,
            0,
            0.08,
            "正在完成全批项目级 Top-K coarse scoring；尚未执行 fine。",
        )
        .unwrap();
        let scoring = get_audio_alignment_batch_job(job_id.clone()).unwrap();
        assert!(scoring.progress >= AUDIO_ALIGNMENT_BATCH_PREPARATION_END_PROGRESS);
        assert_eq!(scoring.current_pair_ordinal, Some(1));
        assert_eq!(scoring.pairs[0].status, AudioAlignmentJobStatus::Running);

        cancel_audio_alignment_batch_worker(&job_id).unwrap();
    }

    #[test]
    fn audio_alignment_batch_planner_preserves_explicit_pair_order_and_cartesian_fallback() {
        let cartesian = plan_audio_alignment_batch(test_audio_alignment_batch_request(None))
            .expect("省略 pairs 时应规划笛卡尔积");
        assert_eq!(
            cartesian.pairing_mode,
            AudioAlignmentBatchPairingMode::FullCartesian
        );
        assert_eq!(cartesian.source_media_ids, ["source-1", "source-2"]);
        assert_eq!(cartesian.target_media_ids, ["target-1", "target-2"]);
        assert_eq!(cartesian.pairs.len(), 4);
        assert_eq!(
            cartesian
                .pairs
                .iter()
                .map(|pair| (
                    pair.pair_index,
                    pair.pair_ordinal,
                    pair.source_media_id.as_str(),
                    pair.target_media_id.as_str()
                ))
                .collect::<Vec<_>>(),
            vec![
                (0, 1, "source-1", "target-1"),
                (1, 2, "source-1", "target-2"),
                (2, 3, "source-2", "target-1"),
                (3, 4, "source-2", "target-2"),
            ]
        );

        let explicit = plan_audio_alignment_batch(test_audio_alignment_batch_request(Some(vec![
            ("source-2", "target-1"),
            ("source-1", "target-2"),
        ])))
        .expect("显式 pairs 应按请求顺序规划");
        assert_eq!(
            explicit.pairing_mode,
            AudioAlignmentBatchPairingMode::Explicit
        );
        assert_eq!(explicit.pairs.len(), 2);
        assert_eq!(explicit.pairs[0].pair_index, 0);
        assert_eq!(explicit.pairs[0].pair_ordinal, 1);
        assert_eq!(explicit.pairs[0].source_media_id, "source-2");
        assert_eq!(explicit.pairs[0].target_media_id, "target-1");
        assert_eq!(explicit.pairs[0].request.source_audio_stream_index, Some(2));
        assert_eq!(
            explicit.pairs[0].request.complete_audio_stream_index,
            Some(11)
        );
        assert_eq!(explicit.pairs[1].pair_ordinal, 2);
        assert_eq!(explicit.pairs[1].pair_index, 1);
        assert_eq!(explicit.pairs[1].source_media_id, "source-1");
        assert_eq!(explicit.pairs[1].target_media_id, "target-2");
        assert_eq!(explicit.media.len(), 4);

        let overlapping_many_to_one =
            plan_audio_alignment_batch(test_audio_alignment_batch_request(Some(vec![
                ("source-1", "target-1"),
                ("source-2", "target-1"),
            ])))
            .expect("显式 many-to-one 应允许不同参考素材复用同一原片区间");
        let target_reuse_groups = overlapping_many_to_one
            .pairs
            .iter()
            .map(|pair| pair.target_axis_reuse_group_ordinal)
            .collect::<Vec<_>>();
        assert_eq!(target_reuse_groups.len(), 2);
        assert!(target_reuse_groups[0].is_some());
        assert_eq!(target_reuse_groups[0], target_reuse_groups[1]);
    }

    #[test]
    fn audio_alignment_batch_full_cartesian_snapshot_is_complete_ordered_and_path_free() {
        let plan = test_plan_with_selected_global_evidence(
            plan_audio_alignment_batch(test_audio_alignment_batch_request(None)).unwrap(),
        );
        let job_id = format!("test-audio-batch-cartesian-evidence-{}", current_time_ms());
        let cancel_flag = Arc::new(AtomicBool::new(false));
        insert_audio_alignment_batch_job(&job_id, &plan, cancel_flag.clone()).unwrap();

        let queued = get_audio_alignment_batch_job(job_id.clone()).unwrap();
        assert_eq!(queued.schema_version, AUDIO_ALIGNMENT_BATCH_SCHEMA_VERSION);
        assert_eq!(
            queued.evidence_version,
            AUDIO_ALIGNMENT_BATCH_EVIDENCE_VERSION
        );
        assert_eq!(
            queued.pairing_mode,
            AudioAlignmentBatchPairingMode::FullCartesian
        );
        assert_eq!(queued.source_media_ids, ["source-1", "source-2"]);
        assert_eq!(queued.target_media_ids, ["target-1", "target-2"]);
        assert!(queued.pairs.iter().all(|pair| {
            pair.global_selection.state == AudioAlignmentBatchGlobalSelectionState::Pending
                && pair.global_selection.top_k.is_empty()
        }));

        run_audio_alignment_batch_job_with_pair_executor(
            job_id.clone(),
            cancel_flag,
            plan,
            |_job_id, pair_index, _pair, _cancel_flag| {
                Ok(test_audio_alignment_batch_proposal(&format!(
                    "cartesian-pair-{pair_index}"
                )))
            },
        );
        let terminal = get_audio_alignment_batch_job(job_id).unwrap();
        assert_eq!(terminal.status, AudioAlignmentJobStatus::Completed);
        assert_eq!(terminal.pairs.len(), 4);
        assert_eq!(
            terminal
                .pairs
                .iter()
                .map(|pair| (
                    pair.pair_index,
                    pair.pair_ordinal,
                    pair.source_media_id.as_str(),
                    pair.target_media_id.as_str()
                ))
                .collect::<Vec<_>>(),
            vec![
                (0, 1, "source-1", "target-1"),
                (1, 2, "source-1", "target-2"),
                (2, 3, "source-2", "target-1"),
                (3, 4, "source-2", "target-2"),
            ]
        );
        assert!(terminal.pairs.iter().all(|pair| {
            pair.status == AudioAlignmentJobStatus::Completed
                && pair.proposal.is_some()
                && pair.global_selection.state == AudioAlignmentBatchGlobalSelectionState::Selected
                && pair.global_selection.selected_rank == Some(1)
                && pair.global_selection.top_k.len() == 1
        }));
        let json = serde_json::to_string(&terminal).unwrap();
        assert!(json.contains("\"pairingMode\":\"fullCartesian\""));
        assert!(json.contains("\"pairIndex\":0"));
        assert!(json.contains("\"globalSelection\""));
        assert!(!json.contains("source-1.mkv"));
        assert!(!json.contains("target-1.mkv"));
        assert!(!json.contains("C:\\\\"));
    }

    #[test]
    fn audio_alignment_batch_global_selection_evidence_keeps_rank_score_and_hides_paths() {
        let candidates = (0..12)
            .map(|index| {
                let start_ms = index as i64 * 100_000;
                v2_test_global_candidate(
                    PresentationRangeMs {
                        start_ms: 0,
                        end_ms: 90_000,
                    },
                    PresentationRangeMs {
                        start_ms,
                        end_ms: start_ms + 90_000,
                    },
                    0.99 - index as f64 * 0.01,
                    false,
                )
            })
            .collect::<Vec<_>>();
        let coarse = Ok(V2PairCoarseCandidates {
            candidates: candidates.clone(),
            temporal_window_groups: Vec::new(),
            alternatives: Vec::new(),
            diagnostics: vec![r"C:\private\source-1.mkv".to_string()],
        });
        let selected_candidate = candidates[10].clone();
        let selected = create_audio_alignment_batch_global_selection_evidence(
            &coarse,
            &V2GlobalShortlistDecision::Selected(PreparedV2SelectedCandidate {
                candidate: selected_candidate.clone(),
                alternatives: Vec::new(),
                global_margin: 0.25,
                global_diagnostic: r"C:\private\target-1.mkv".to_string(),
            }),
            0,
        )
        .unwrap();
        validate_audio_alignment_batch_global_selection_evidence(&selected, true).unwrap();
        assert_eq!(
            selected.state,
            AudioAlignmentBatchGlobalSelectionState::Selected
        );
        assert_eq!(selected.candidate_count, 12);
        assert_eq!(selected.eligible_candidate_count, 12);
        assert_eq!(selected.top_k.len(), AUDIO_ALIGNMENT_BATCH_EVIDENCE_TOP_K);
        assert_eq!(selected.selected_rank, Some(11));
        assert_eq!(selected.decision_rank, Some(11));
        assert_eq!(
            selected.selected_score.map(f64::to_bits),
            Some(v2_global_candidate_weight(&selected_candidate).to_bits())
        );
        assert!(selected
            .top_k
            .iter()
            .all(|candidate| !candidate.global_selected));
        assert_eq!(
            selected
                .decision_candidate
                .as_ref()
                .map(|candidate| candidate.rank),
            Some(11)
        );
        assert!(selected
            .decision_candidate
            .as_ref()
            .is_some_and(|candidate| candidate.global_selected));
        let selected_json = serde_json::to_string(&selected).unwrap();
        assert!(!selected_json.contains("private"));
        assert!(!selected_json.contains(".mkv"));

        let blocked = create_audio_alignment_batch_global_selection_evidence(
            &coarse,
            &V2GlobalShortlistDecision::Blocked {
                candidate: Some(candidates[1].clone()),
                alternatives: Vec::new(),
                margin: 0.01,
                reason: r"C:\private\must-not-leak.mkv".to_string(),
                diagnostics: vec![r"C:\private\diagnostic.mkv".to_string()],
            },
            0,
        )
        .unwrap();
        validate_audio_alignment_batch_global_selection_evidence(&blocked, true).unwrap();
        assert_eq!(
            blocked.state,
            AudioAlignmentBatchGlobalSelectionState::Blocked
        );
        assert!(!blocked.selected);
        assert_eq!(blocked.decision_rank, Some(2));
        assert!(blocked
            .top_k
            .iter()
            .all(|candidate| !candidate.global_selected));
        let blocked_json = serde_json::to_string(&blocked).unwrap();
        assert!(!blocked_json.contains("private"));
        assert!(!blocked_json.contains(".mkv"));

        let failed_coarse: Result<V2PairCoarseCandidates, String> =
            Err(r"C:\private\coarse-failure.mkv".to_string());
        let failed = create_audio_alignment_batch_global_selection_evidence(
            &failed_coarse,
            &V2GlobalShortlistDecision::Failed(r"C:\private\shortlist-failure.mkv".to_string()),
            0,
        )
        .unwrap();
        validate_audio_alignment_batch_global_selection_evidence(&failed, false).unwrap();
        assert_eq!(
            failed.state,
            AudioAlignmentBatchGlobalSelectionState::Failed
        );
        let failed_json = serde_json::to_string(&failed).unwrap();
        assert!(!failed_json.contains("private"));
        assert!(!failed_json.contains(".mkv"));
    }

    #[test]
    fn audio_alignment_batch_relation_ranking_is_shard_invariant_and_searches_beyond_top_ten() {
        let relation_candidate = v2_test_global_candidate(
            PresentationRangeMs {
                start_ms: 0,
                end_ms: 90_000,
            },
            PresentationRangeMs {
                start_ms: 300_000,
                end_ms: 390_000,
            },
            0.80,
            false,
        );
        let competing_candidate = v2_test_global_candidate(
            PresentationRangeMs {
                start_ms: 0,
                end_ms: 90_000,
            },
            PresentationRangeMs {
                start_ms: 300_000,
                end_ms: 390_000,
            },
            0.99,
            false,
        );
        let relation_coarse = Ok(V2PairCoarseCandidates {
            candidates: vec![relation_candidate],
            temporal_window_groups: Vec::new(),
            alternatives: Vec::new(),
            diagnostics: Vec::new(),
        });
        let competing_coarse = Ok(V2PairCoarseCandidates {
            candidates: vec![competing_candidate],
            temporal_window_groups: Vec::new(),
            alternatives: Vec::new(),
            diagnostics: Vec::new(),
        });
        let mut isolated_plan = test_one_source_three_target_batch_plan();
        isolated_plan.pairs.truncate(1);
        let isolated_decisions = select_v2_global_shortlist(
            &isolated_plan,
            std::slice::from_ref(&relation_coarse),
            0,
            None,
        )
        .unwrap();
        assert!(matches!(
            isolated_decisions.first(),
            Some(V2GlobalShortlistDecision::Selected(_))
        ));

        let mut conflict_plan = test_one_source_three_target_batch_plan();
        conflict_plan.pairs.truncate(2);
        let conflict_decisions = select_v2_global_shortlist(
            &conflict_plan,
            &[relation_coarse.clone(), competing_coarse],
            0,
            None,
        )
        .unwrap();
        assert!(matches!(
            conflict_decisions.first(),
            Some(V2GlobalShortlistDecision::Blocked { .. })
        ));
        assert!(matches!(
            conflict_decisions.get(1),
            Some(V2GlobalShortlistDecision::Selected(_))
        ));
        let isolated_relation = create_audio_alignment_batch_relation_ranking_evidence(
            &relation_coarse,
            Ok(test_audio_alignment_batch_execution_identity()),
        )
        .unwrap();
        let conflicted_relation = create_audio_alignment_batch_relation_ranking_evidence(
            &relation_coarse,
            Ok(test_audio_alignment_batch_execution_identity()),
        )
        .unwrap();
        assert_eq!(
            serde_json::to_string(&isolated_relation).unwrap(),
            serde_json::to_string(&conflicted_relation).unwrap(),
            "同一 pair 的 relationRanking 不得随 tile-local conflict 上下文变化"
        );

        let mut candidates = (0..12)
            .map(|index| {
                let start_ms = index as i64 * 100_000;
                let mut candidate = v2_test_global_candidate(
                    PresentationRangeMs {
                        start_ms: 0,
                        end_ms: 90_000,
                    },
                    PresentationRangeMs {
                        start_ms,
                        end_ms: start_ms + 90_000,
                    },
                    0.99 - index as f64 * 0.01,
                    false,
                );
                candidate.hypothesis.unique_source_coverage = 0.0;
                candidate
            })
            .collect::<Vec<_>>();
        candidates[11].hypothesis.unique_source_coverage = 1.0;
        candidates[11].fine_working_set_bytes = usize::MAX;
        let coarse = Ok(V2PairCoarseCandidates {
            candidates,
            temporal_window_groups: Vec::new(),
            alternatives: Vec::new(),
            diagnostics: Vec::new(),
        });

        let first = create_audio_alignment_batch_relation_ranking_evidence(
            &coarse,
            Ok(test_audio_alignment_batch_execution_identity()),
        )
        .unwrap();
        let second = create_audio_alignment_batch_relation_ranking_evidence(
            &coarse,
            Ok(test_audio_alignment_batch_execution_identity()),
        )
        .unwrap();

        validate_audio_alignment_batch_relation_ranking_evidence(&first, true).unwrap();
        assert_eq!(first.state, AudioAlignmentBatchRelationRankingState::Ranked);
        assert_eq!(first.candidate_count, 12);
        assert_eq!(first.eligible_candidate_count, 12);
        assert_eq!(
            first
                .best_eligible_candidate
                .as_ref()
                .map(|candidate| candidate.rank),
            Some(12),
            "relation ranking 必须检查完整 coarse 候选，而不是只看公开 Top-10"
        );
        assert_eq!(
            first.score.map(f64::to_bits),
            second.score.map(f64::to_bits),
            "relation score 不得受 tile-local conflict、fine budget 或 shortlist 上下文影响"
        );
        assert_eq!(
            serde_json::to_string(&first).unwrap(),
            serde_json::to_string(&second).unwrap()
        );

        let no_eligible = create_audio_alignment_batch_relation_ranking_evidence(
            &Ok(V2PairCoarseCandidates {
                candidates: Vec::new(),
                temporal_window_groups: Vec::new(),
                alternatives: Vec::new(),
                diagnostics: Vec::new(),
            }),
            Ok(test_audio_alignment_batch_execution_identity()),
        )
        .unwrap();
        validate_audio_alignment_batch_relation_ranking_evidence(&no_eligible, true).unwrap();
        assert_eq!(
            no_eligible.state,
            AudioAlignmentBatchRelationRankingState::NoEligibleCandidate
        );
        assert!(no_eligible.execution_identity_digest.is_some());
        assert!(no_eligible.execution_identity.is_some());
    }

    #[test]
    fn audio_alignment_batch_execution_identity_digest_binds_build_toolchain_backend_and_fallback()
    {
        let (digest, identity) = test_audio_alignment_batch_execution_identity();
        validate_audio_alignment_batch_execution_identity(&digest, &identity).unwrap();

        let mut mutations = Vec::new();
        let mut executable_drift = identity.clone();
        executable_drift.native_executable_digest = format!("sha256:{}", "d".repeat(64));
        mutations.push(executable_drift);
        let mut ffmpeg_drift = identity.clone();
        ffmpeg_drift.ffmpeg_binary_digest = format!("sha256:{}", "e".repeat(64));
        mutations.push(ffmpeg_drift);
        let mut backend_drift = identity.clone();
        backend_drift.source_spectral_backends[0].backend_id =
            crate::cuda_fft_backend::CUDA_FFT_BACKEND_ID.to_string();
        mutations.push(backend_drift);
        let mut fallback_drift = identity.clone();
        fallback_drift.source_spectral_backends[0].requested_backend = "auto".to_string();
        fallback_drift.source_spectral_backends[0].fallback_reason =
            Some("CUDA runtime failure; explicit CPU fallback".to_string());
        mutations.push(fallback_drift);

        for mutation in mutations {
            assert!(validate_audio_alignment_batch_execution_identity(&digest, &mutation).is_err());
        }

        let mut duplicate = identity;
        duplicate
            .source_spectral_backends
            .push(duplicate.source_spectral_backends[0].clone());
        assert!(validate_audio_alignment_batch_execution_identity(&digest, &duplicate).is_err());
    }

    #[test]
    fn audio_alignment_batch_planner_accepts_one_by_256_and_rejects_one_by_257() {
        let create_request = |target_count: usize| AudioAlignmentBatchRequest {
            schema_version: AUDIO_ALIGNMENT_BATCH_SCHEMA_VERSION,
            sources: vec![AudioAlignmentBatchMediaRequest {
                media_id: "source-1".to_string(),
                path: "source-1.mkv".to_string(),
                audio_stream_index: Some(0),
                video_stream_index: None,
            }],
            targets: (0..target_count)
                .map(|index| AudioAlignmentBatchMediaRequest {
                    media_id: format!("target-{index:03}"),
                    path: format!("target-{index:03}.mkv"),
                    audio_stream_index: Some(0),
                    video_stream_index: None,
                })
                .collect(),
            pairs: None,
            version_reuse_groups: Vec::new(),
            ffmpeg_path: None,
            ffprobe_path: None,
            spectral_backend: Some(SpectralBackendPreference::Cpu),
            sample_rate: None,
            window_ms: None,
            match_threshold: None,
            min_gap_ms: None,
            max_cells: Some(DEFAULT_MAX_CELLS),
            enable_visual_evidence: Some(false),
            visual_sample_interval_ms: None,
            localization_mode: Some(true),
        };

        let accepted = plan_audio_alignment_batch(create_request(256)).unwrap();
        assert_eq!(accepted.pairs.len(), 256);
        let error = match plan_audio_alignment_batch(create_request(257)) {
            Ok(_) => panic!("1x257 必须超过 native batch 上限"),
            Err(error) => error,
        };
        assert!(error.contains("1–256") || error.contains("最多允许 256 个 pair"));
    }

