    fn test_plan_with_selected_global_evidence(
        mut plan: PlannedAudioAlignmentBatch,
    ) -> PlannedAudioAlignmentBatch {
        for (pair_index, pair) in plan.pairs.iter_mut().enumerate() {
            let candidate = AudioAlignmentBatchGlobalCandidateSnapshot {
                rank: 1,
                source_stream_index: pair.request.source_audio_stream_index.unwrap_or(0),
                target_stream_index: pair.request.complete_audio_stream_index.unwrap_or(0),
                score: 0.9,
                global_score: 0.8,
                scale: 1.0,
                offset_ms: pair_index as i64 * 1_000,
                source_start_ms: pair_index as i64 * 10_000,
                source_end_ms: pair_index as i64 * 10_000 + 9_000,
                target_start_ms: pair_index as i64 * 10_000,
                target_end_ms: pair_index as i64 * 10_000 + 9_000,
                inlier_count: 12,
                temporal_coverage: 0.9,
                unique_source_coverage: 0.85,
                eligible: true,
                global_selected: true,
            };
            let (execution_identity_digest, execution_identity) =
                test_audio_alignment_batch_execution_identity();
            pair.relation_ranking = AudioAlignmentBatchRelationRankingSnapshot {
                score_version: AUDIO_ALIGNMENT_BATCH_RELATION_SCORE_VERSION,
                execution_identity_digest: Some(execution_identity_digest),
                execution_identity: Some(execution_identity),
                state: AudioAlignmentBatchRelationRankingState::Ranked,
                candidate_count: 1,
                eligible_candidate_count: 1,
                score: Some(candidate.global_score),
                best_eligible_candidate: Some(AudioAlignmentBatchRelationCandidateSnapshot {
                    rank: candidate.rank,
                    source_stream_index: candidate.source_stream_index,
                    target_stream_index: candidate.target_stream_index,
                    score: candidate.score,
                    global_score: candidate.global_score,
                    scale: candidate.scale,
                    offset_ms: candidate.offset_ms,
                    source_start_ms: candidate.source_start_ms,
                    source_end_ms: candidate.source_end_ms,
                    target_start_ms: candidate.target_start_ms,
                    target_end_ms: candidate.target_end_ms,
                    inlier_count: candidate.inlier_count,
                    temporal_coverage: candidate.temporal_coverage,
                    unique_source_coverage: candidate.unique_source_coverage,
                }),
            };
            pair.global_selection = AudioAlignmentBatchGlobalSelectionSnapshot {
                state: AudioAlignmentBatchGlobalSelectionState::Selected,
                selected: true,
                selected_rank: Some(1),
                selected_score: Some(candidate.global_score),
                decision_rank: Some(1),
                decision_score: Some(candidate.global_score),
                margin: Some(0.5),
                candidate_count: 1,
                eligible_candidate_count: 1,
                top_k: vec![candidate.clone()],
                decision_candidate: Some(candidate),
            };
        }
        plan
    }

    #[test]
    fn batch_persistent_diagnostics_bind_run_id_and_events_without_media_paths() {
        let plan = plan_audio_alignment_batch(test_audio_alignment_batch_request(Some(vec![(
            "source-1", "target-1",
        )])))
        .unwrap();
        let job_id = batch_jobs::next_test_job_id("test-audio-batch-diagnostic");
        let root = std::env::temp_dir().join(&job_id);
        let cancel_flag = Arc::new(AtomicBool::new(false));
        insert_audio_alignment_batch_job_with_diagnostics(
            &job_id,
            &plan,
            cancel_flag,
            Some(Ok(root.clone())),
            None,
        )
        .unwrap();
        append_audio_alignment_batch_diagnostic_event(
            &job_id,
            AudioAlignmentBatchDiagnosticLevel::Info,
            "test.stage",
            Some(1),
            None,
            "脱敏阶段完成。",
            Some(25),
        )
        .unwrap();

        let snapshot = get_audio_alignment_batch_job(job_id.clone()).unwrap();
        assert_eq!(snapshot.diagnostic_events.len(), 3);
        assert_eq!(
            snapshot.diagnostic_events[1].stage_key,
            "logging.persistence-enabled"
        );
        let content =
            fs::read_to_string(root.join(format!("{job_id}.jsonl"))).expect("read diagnostic log");
        assert!(content.contains(&format!(r#""runId":"{job_id}""#)));
        assert!(content.contains(r#""stageKey":"test.stage""#));
        assert!(!content.contains("source.mp4"));
        assert!(!content.contains("target.mp4"));

        batch_jobs::remove_job(&job_id).unwrap();
        fs::remove_dir_all(root).expect("cleanup diagnostic root");
    }

    #[test]
    fn batch_sensitive_manifest_binds_paths_streams_plan_and_terminal_snapshot() {
        let plan = plan_audio_alignment_batch(test_audio_alignment_batch_request(Some(vec![(
            "source-1", "target-1",
        )])))
        .unwrap();
        let job_id = batch_jobs::next_test_job_id("test-audio-batch-sensitive");
        let root = std::env::temp_dir().join(&job_id);
        insert_audio_alignment_batch_job_with_diagnostics(
            &job_id,
            &plan,
            Arc::new(AtomicBool::new(false)),
            None,
            Some(Ok(root.clone())),
        )
        .unwrap();

        let queued: serde_json::Value = serde_json::from_slice(
            &fs::read(root.join(format!("{job_id}.json"))).expect("read queued manifest"),
        )
        .expect("parse queued manifest");
        assert_eq!(queued["payload"]["lifecycleStage"], "queued");
        assert_eq!(
            queued["payload"]["plan"]["media"][0]["path"],
            "source-1.mkv"
        );
        assert_eq!(
            queued["payload"]["plan"]["media"][0]["requestedAudioStreamIndex"],
            1
        );
        assert_eq!(
            queued["payload"]["plan"]["media"][0]["requestedVideoStreamIndex"],
            3
        );
        assert_eq!(
            queued["payload"]["plan"]["pairs"][0]["targetMediaOrdinal"],
            2
        );
        assert_eq!(
            queued["payload"]["plan"]["parameters"]["requestedSpectralBackend"],
            "cpu"
        );
        assert!(queued["payload"]["plan"]["parametersDigest"]
            .as_str()
            .is_some_and(|digest| digest.starts_with("sha256:") && digest.len() == 71));
        let active_summaries =
            sensitive_manifest_journal::read_alignment_sensitive_manifest_summaries(&root)
                .expect("active queued journal remains visible");
        assert_eq!(active_summaries.len(), 1);
        assert_eq!(active_summaries[0].run_id, job_id);
        assert_eq!(active_summaries[0].lifecycle_stage, "queued");

        fail_audio_alignment_batch_worker_with_error(&job_id, 0, "blocked:test-sensitive-manifest")
            .unwrap();
        let terminal: serde_json::Value = serde_json::from_slice(
            &fs::read(root.join(format!("{job_id}.json"))).expect("read terminal manifest"),
        )
        .expect("parse terminal manifest");
        assert_eq!(terminal["payload"]["lifecycleStage"], "terminal");
        assert_eq!(terminal["payload"]["snapshot"]["status"], "failed");
        assert_eq!(terminal["payload"]["snapshot"]["jobId"], job_id);
        assert_ne!(queued["payloadDigest"], terminal["payloadDigest"]);
        assert!(terminal["payload"]["snapshot"]["diagnosticEvents"]
            .as_array()
            .is_some_and(|events| events
                .iter()
                .any(|event| { event["stageKey"] == "logging.sensitive-manifest-enabled" })));
        let terminal_summary: serde_json::Value = serde_json::from_slice(
            &fs::read(root.join(format!("{job_id}.summary"))).expect("read terminal summary"),
        )
        .expect("parse terminal summary");
        assert_eq!(terminal_summary["summary"]["runId"], job_id);
        assert_eq!(
            terminal_summary["summary"]["manifestPayloadDigest"],
            terminal["payloadDigest"]
        );
        assert_eq!(terminal_summary["summary"]["lifecycleStage"], "terminal");
        assert_eq!(terminal_summary["summary"]["intakeState"], "unusable");
        assert_eq!(terminal_summary["summary"]["readyForTrainingIntake"], false);

        batch_jobs::apply_event(
            &job_id,
            batch_jobs::AudioAlignmentBatchJobEvent::SensitivePrepared(Vec::new()),
        )
        .expect("late prepared event is an idempotent no-op");
        let still_terminal: serde_json::Value = serde_json::from_slice(
            &fs::read(root.join(format!("{job_id}.json"))).expect("read monotonic terminal"),
        )
        .expect("parse monotonic terminal");
        assert_eq!(still_terminal["payload"]["lifecycleStage"], "terminal");
        assert_eq!(still_terminal["payload"]["snapshot"]["status"], "failed");

        batch_jobs::remove_job(&job_id).unwrap();
        fs::remove_dir_all(root).expect("cleanup sensitive manifest root");
    }

    #[test]
    fn batch_get_retries_a_terminal_sensitive_manifest_after_atomic_replace_recovers() {
        let plan = plan_audio_alignment_batch(test_audio_alignment_batch_request(Some(vec![(
            "source-1", "target-1",
        )])))
        .unwrap();
        let job_id = batch_jobs::next_test_job_id("test-audio-batch-sensitive-retry");
        let root = std::env::temp_dir().join(&job_id);
        insert_audio_alignment_batch_job_with_diagnostics(
            &job_id,
            &plan,
            Arc::new(AtomicBool::new(false)),
            None,
            Some(Ok(root.clone())),
        )
        .unwrap();
        let manifest_path = root.join(format!("{job_id}.json"));
        fs::remove_file(&manifest_path).expect("remove queued manifest");
        fs::create_dir(&manifest_path).expect("block terminal manifest replacement");

        complete_audio_alignment_batch_pair(
            &job_id,
            0,
            Some(test_audio_alignment_batch_proposal("terminal-retry")),
            None,
        )
        .unwrap();
        finalize_audio_alignment_batch_job(&job_id).unwrap();
        let failed_write_snapshot = get_audio_alignment_batch_job(job_id.clone()).unwrap();
        assert_eq!(
            failed_write_snapshot.status,
            AudioAlignmentJobStatus::Completed
        );
        assert!(failed_write_snapshot
            .diagnostic_events
            .iter()
            .any(|event| { event.stage_key == "logging.sensitive-manifest-unavailable" }));
        let summary_path = root.join(format!("{job_id}.summary"));
        assert!(
            !summary_path.exists(),
            "failed terminal replacement must not leave a queued/prepared summary visible"
        );

        fs::remove_dir(&manifest_path).expect("unblock terminal manifest replacement");
        let retried_snapshot = get_audio_alignment_batch_job(job_id.clone()).unwrap();
        assert_eq!(retried_snapshot.status, AudioAlignmentJobStatus::Completed);
        let terminal: serde_json::Value = serde_json::from_slice(
            &fs::read(&manifest_path).expect("read retried terminal manifest"),
        )
        .expect("parse retried terminal manifest");
        assert_eq!(terminal["payload"]["lifecycleStage"], "terminal");
        assert_eq!(terminal["payload"]["snapshot"]["status"], "completed");
        assert_eq!(terminal["payload"]["snapshot"]["jobId"], job_id);

        batch_jobs::remove_job(&job_id).unwrap();
        fs::remove_dir_all(root).expect("cleanup sensitive manifest retry root");
    }

    #[test]
    fn batch_get_retries_a_sensitive_summary_without_repeating_the_warning() {
        let plan = plan_audio_alignment_batch(test_audio_alignment_batch_request(Some(vec![(
            "source-1", "target-1",
        )])))
        .unwrap();
        let job_id = batch_jobs::next_test_job_id("test-audio-batch-sensitive-summary-retry");
        let root = std::env::temp_dir().join(&job_id);
        insert_audio_alignment_batch_job_with_diagnostics(
            &job_id,
            &plan,
            Arc::new(AtomicBool::new(false)),
            None,
            Some(Ok(root.clone())),
        )
        .unwrap();
        let summary_path = root.join(format!("{job_id}.summary"));
        fs::remove_file(&summary_path).expect("remove queued summary");
        fs::create_dir(&summary_path).expect("block terminal summary replacement");

        fail_audio_alignment_batch_worker_with_error(&job_id, 0, "blocked:test-sensitive-summary")
            .unwrap();
        let first_retry = get_audio_alignment_batch_job(job_id.clone()).unwrap();
        let second_retry = get_audio_alignment_batch_job(job_id.clone()).unwrap();
        let warning_count = second_retry
            .diagnostic_events
            .iter()
            .filter(|event| event.stage_key == "logging.sensitive-summary-unavailable")
            .count();
        assert_eq!(first_retry.status, AudioAlignmentJobStatus::Failed);
        assert_eq!(second_retry.status, AudioAlignmentJobStatus::Failed);
        assert_eq!(warning_count, 1, "polling must not duplicate the warning");

        fs::remove_dir(&summary_path).expect("unblock terminal summary replacement");
        let recovered = get_audio_alignment_batch_job(job_id.clone()).unwrap();
        assert_eq!(recovered.status, AudioAlignmentJobStatus::Failed);
        let terminal_summary: serde_json::Value = serde_json::from_slice(
            &fs::read(&summary_path).expect("read recovered terminal summary"),
        )
        .expect("parse recovered terminal summary");
        assert_eq!(terminal_summary["summary"]["lifecycleStage"], "terminal");
        assert_eq!(terminal_summary["summary"]["status"], "failed");

        batch_jobs::remove_job(&job_id).unwrap();
        fs::remove_dir_all(root).expect("cleanup sensitive summary retry root");
    }

